p=pathlib.Path('assets/js/dashboard-help-data.js');s=p.read_text();d=json.loads(s.split('window.SSMPDHelpData=',1)[1].strip().removesuffix(';'))
rows=json.loads(subprocess.check_output(['node','scripts/help-field-inventory.cjs','--json'],text=True));rules=[]
def rule(labels,text,article=None):
 rules.append((set(labels.split('|')),text,article))
rule('ملاحظات الخزينة','اكتب وصفًا للعهدة أو تعليمات الاستلام. الملاحظة لا تغير صلاحيات الخزينة.','ledger-guide')
rule('نوع الكشف','اختر كشف ماكينة الفيزا أو البنك أو المحفظة ليقارن النظام الحركات بالحساب المقابل.','ledger-guide')
rule('البنك أو شركة التحصيل|شركة التحصيل أو البنك','اكتب الجهة التي أصدرت الكشف أو الإيصال، مثل فوري أو اسم البنك.','ledger-guide')
rule('رابط أصل الكشف على Google Drive — اختياري|رابط الإيصال على Google Drive — اختياري','ضع رابط المستند الموجود على Google Drive إذا أردت الاحتفاظ بمرجع الأصل. اختيار الملف هنا لا يرفعه تلقائيًا.','ledger-guide')
rule('ملف PDF أو Excel أو CSV','اختر ملفًا حتى20 ميجابايت. راجع كل السطور المستخرجة وعددها وإجماليها قبل الحفظ. الحد500 عملية و50 صفحة للكشف.','ledger-guide')
rule('استخدام قراءة الصور OCR للصفحات الممسوحة على الجهاز','فعّل قبل اختيار الملف لقراءة الصفحات المصورة على جهازك. راجع الأرقام لأن القراءة قد تخطئ.','ledger-guide')
rule('عدد العمليات بعد مقارنته بأصل الكشف','اكتب عدد العمليات بعد مراجعة كل صفحات الكشف. يجب أن يساوي عدد السطور التي ستحفظ.','ledger-guide')
rule('إجمالي المبالغ بإشارتها بعد مراجعته بالكشف','اكتب مجموع الداخل موجبًا والخارج سالبًا بعد المقارنة بأصل الكشف. يجب أن يساوي مجموع المعاينة.','ledger-guide')
rule('راجعت كل الصفحات والمراجع والمبالغ والعدد والإجمالي مقابل أصل الكشف','أكد بعد فحص الصفحات والعمليات والمراجع بنفسك. القراءة الآلية ليست اعتمادًا لصحة الكشف.','ledger-guide')
rule('دليل الربط وسبب التجميع','اشرح مرجع التسوية أو المستند الذي يثبت أن مجموع الحركات المختارة يمثل سطر الكشف.','ledger-guide')
rule('الموظف المكلف بالمراجعة','اختر الموظف المطلوب منه التحقق. التكليف لا يعني أنه مسؤول عن الفرق.','ledger-guide')
rule('موعد الرد','حدد موعدًا قادمًا لرد الموظف على مهمة مراجعة الاختلاف.','ledger-guide')
rule('المطلوب مراجعته','اكتب المطلوب من الموظف ودليل التحقق، دون إدراج بيانات طبية في المهمة.','ledger-guide')
rule('الرقم المرجعي في الإيصال','انقل مرجع عملية الدفع من الإيصال. لا تستخدم رقم الفاتورة بدل مرجع شركة التحصيل.','ledger-guide')
rule('RRN — اختياري','انقل حقل RRN كما يظهر في إيصال الماكينة إن وجد. لا تدخل رقم البطاقة.','ledger-guide')
rule('كود الماكينة — اختياري','انقل كود الماكينة من الإيصال لتمييز الجهاز الذي سجل التحصيل.','ledger-guide')
rule('ابحث في الشجرة|البحث بالكود أو اسم الحساب','اكتب جزءًا من اسم الحساب أو كوده لعرض موضعه في الشجرة. البحث لا يغير الحسابات.','ledger-guide')
rule('نوع الحساب','اختر أصلًا أو التزامًا أو حقوق ملكية أو إيرادًا أو مصروفًا. نوع الابن يجب أن يطابق نوع الأب.','ledger-guide')
rule('المستوى المحسوب من الأب|المستوى','المستوى الأول بلا أب، وكل ابن يزيد مستوى واحدًا. الحد خمسة مستويات. في معاينة الاستيراد يجب أن يتطابق المستوى مع الأب.','ledger-guide')
rule('حالة الحساب','اختر مفعّلًا للسماح باستخدام الحساب أو موقوفًا لمنع الحركات الجديدة. لا يمكن إيقاف حساب نظام أو حساب مرتبط بخزينة أو له أبناء مفعّلون.','ledger-guide')
rule('طبيعة الحساب','الحساب التجميعي يجمع أبناءه ولا يقبل قيودًا مباشرة. حساب الحركة يقبل قيودًا ولا يضم حسابات أبناء.','ledger-guide')
rule('دور الخزينة','اختر الرئيسية للصرف والاستلام، أو خزينة تحصيل لتلقي النقد وتسليمه إلى الرئيسية. يسمح النظام برئيسية واحدة.','ledger-guide')
rule('حساب الخزينة في الشجرة','اختر حساب أصل مفعّلًا قابلًا للحركة ومخصصًا لهذه الخزينة. لا تشارك خزينتان نفس الحساب، ولا يتغير ربط حركة قديمة.','ledger-guide')
rule('الخزينة الرئيسية المستلمة','اختر الخزينة الرئيسية التي تستلم حصيلة خزينة التحصيل. افتح وردية للمستلم قبل اعتماد التسليم.','ledger-guide')
rule('حد النثريات للإذن بالجنيه','أدخل حد الإذن بالصرف. خزينة التحصيل حدها صفر، والصرف من الرئيسية يخضع للرصيد والاعتماد.','ledger-guide')
rule('راجعت الأكواد والأسماء والأب والمستويات قبل الإضافة','حدد هذا الاختيار بعد مراجعة كل صف في المعاينة. أي تعديل أو اقتراح جديد يحتاج مراجعة جديدة. المعاينة لا تحفظ حسابات تلقائيًا.','ledger-guide')
rule('اقتراح الكود تلقائيًا من الأب — يمكنك تعديله','فعّل الاختيار ليقترح النظام كودًا متاحًا تحت الأب. تغيير الكود يدويًا يوقف الاقتراح؛ عند الحفظ يعيد النظام التحقق من عدم التكرار ويحافظ على أكواد الحسابات السابقة.','ledger-guide')
rule('كود الأب','أدخل كود الحساب التجميعي الذي يتبعه هذا الحساب. اتركه فارغًا للمستوى الأول فقط.','ledger-guide')
rule('وردية التحصيل المفتوحة','اختر ورديتك المفتوحة التي ستسلم حصيلتها. لا يمكنك اختيار وردية موظف آخر.','ledger-guide')
rule('المبلغ المسلّم فعليًا بالجنيه','أدخل النقد الذي ستسلمه فعليًا. لا يتجاوز رصيد الوردية بعد طرح التسليمات المعلقة، ولا يتغير الرصيد حتى اعتماد المستلم.','ledger-guide')
rule('رقم مستند التسليم','اكتب رقم سند التسليم الذي يرجع إليه الطرفان عند المراجعة. لا تكرر رقم سند سابق.','ledger-guide')
rule('سبب التسليم','اكتب سبب التحويل مثل تسليم حصيلة اليوم إلى الخزينة الرئيسية.','ledger-guide')
rule('ملاحظة الاستلام أو سبب الرفض','بعد عدّ النقد اكتب ملاحظة الاستلام، أو سبب الرفض عند عدم استلامه. لا يعتمد مقدم الطلب طلبه بنفسه.','ledger-guide')
rule('نص Brief المواعيد','نص للنسخ إلى إضافة منشئ محتوى عيادات سونو. يحتوي اليوم والأسماء والتخصصات والساعات كما أدخلتها، وتعليمات صياغة المنشور دون تغيير الجدول. انسخه للإضافة ثم استورد الرد لاختيار النص.','design-guide')
rule('نوع التصميم والنشر','اختر منشور 1080×1350 أو ستوري فقط 1080×1920. يحفظ الاختيار مع نسخة التصميم ويستخدمه عامل النشر بعد الاعتماد. الستوري لا تنشر بوستًا في الصفحة، والنص المولد يبقى للمراجعة ولا يظهر ككابشن داخل الستوري.','design-guide')
rule('يوم جدول العيادات','اختر اليوم الذي يخصه منشور المواعيد. يظهر اسم اليوم في أعلى التصميم، ولا يغير مواعيد الحجز الفعلية.','design-guide')
rule('اسم الطبيب في جدول اليوم','اكتب اسم الطبيب كما سيظهر للجمهور. راجع الاسم قبل إرسال المادة للاعتماد. هذا الحقل يخص المنشور ولا ينشئ طبيبًا أو عقدًا.','design-guide')
rule('تخصص العيادة في الجدول','اكتب التخصص المختصر الذي سيظهر بجانب اسم الطبيب. راجع أن النص يناسب مساحة المعاينة؛ لا يغير تخصص الخدمات.','design-guide')
rule('بداية موعد العيادة|نهاية موعد العيادة','اختر الساعة والدقيقة مع صباحًا أو مساءً من حقل الوقت. النهاية الأقل من البداية تعني اليوم التالي؛ يجب اختلاف البداية والنهاية. هذه أوقات المنشور فقط وليست حجزًا لمريض.','design-guide')
# Each rule is an authored explanation for the listed source labels, not a word-based runtime guess.
rule('الصفحة|المادة دي لصفحة','اختار الصفحة التي ستنشر باسمها المادة، سونو أو د. دينا. الاختيار يحدد هوية المحتوى والتخصص والذاكرة المستخدمة، ولا يربط حسابًا جديدًا بالسوشيال.','content')
rule('عدد الأفكار','اختار عدد الأفكار المطلوب تجهيزها لخطة الأسبوع القادم. الخيارات الحالية 7 أو 10 أو 14 أو 21. العدد يخص الأفكار التي يطلبها الـBrief من الوكيل، وليس عدد أيام الأسبوع أو أمر نشر تلقائي.','weekly-planning')
rule('هدف البوست|الهدف الإعلاني|الهدف (Objective)','حدد النتيجة المطلوبة من المحتوى أو الحملة، مثل التوعية أو بناء الثقة أو رسائل واتساب. الهدف يوجّه الفكرة والدعوة للتفاعل، ولا يثبت أن النتيجة تحققت.','content-brief')
rule('شكل المحتوى|شكل المحتوى (اختياري)','اختار بوست صورة أو كاروسيل أو فيديو/ريل حسب المطلوب. الاختيار يحدد الحقول وطريقة الإنتاج، ولا يعني أن التصميم أو الفيديو تم إنشاؤه.','content-brief')
rule('الموضوع / الخدمة|الموضوع / الخدمة (اختياري)|الموضوع أو توجيه إضافي','اكتب موضوع المادة أو الخدمة المقصودة مع توجيه محدد، مثل توعية عن الصداع المتكرر. لا تضع بيانات مريض أو وعود علاجية غير معتمدة.','content-brief')
rule('Hook','اكتب الجملة الافتتاحية التي تظهر أو تقال في بداية المحتوى لجذب الانتباه للموضوع، مثل سؤال يعبّر عن مشكلة الجمهور. لا تستخدمها بدل نص المنشور كله.','content-brief')
rule('Angle','اكتب زاوية تناول الموضوع، مثل تصحيح اعتقاد شائع أو شرح متى يطلب الشخص تقييمًا طبيًا. تختلف عن العنوان وعن الجملة الافتتاحية.','content-brief')
rule('سكريبت / Voice-over|نص التعليق الصوتي','اكتب النص الذي سيُقال في الصوت أو الفيديو بالترتيب المطلوب. راجع نطق الأسماء والأرقام، وطابق طول النص مع مدة الفيديو قبل التوليد.','video-guide')
rule('كابشن النشر','اكتب نص المنشور الذي سيظهر مع الصورة أو الفيديو على المنصة. الكابشن يختلف عن الكلام المكتوب داخل التصميم وعن سكريبت الصوت.','content-brief')
rule('نوع CTA','اكتب نوع الإجراء الذي تريد من الجمهور تنفيذه حسب النموذج، مثل save_share أو whatsapp أو book. طابقه مع الهدف ومع نص الدعوة المكتوب.','content-brief')
rule('نص CTA|الدعوة للتفاعل','اكتب الجملة التي تطلب بها الإجراء من الجمهور، مثل «احفظ المنشور» أو «تواصل للحجز». اختر طلبًا واحدًا يناسب هدف المادة.','content-brief')
rule('أقل مدة (ث)|أقل مدة بالثواني','اكتب الحد الأدنى لمدة الفيديو بالثواني، مثل 20، وليس بالدقائق. يجب ألا يزيد عن الحد الأقصى، وتظل المدة النهائية مرتبطة بالنص والمشاهد.','video-guide')
rule('أقصى مدة (ث)|أقصى مدة بالثواني','اكتب الحد الأقصى لمدة الفيديو بالثواني، مثل 45. اجعله مساويًا للحد الأدنى أو أكبر منه وراجع ملاءمة السكريبت.','video-guide')
rule('Video Template','اكتب معرّف قالب الفيديو الذي يقبله مسار الإنتاج، مثل medical_educational إذا كان هو القالب المطلوب. هذا معرّف قالب، وليس عنوان المنشور.','video-guide')
rule('سبب الفرضية / Evidence note','اكتب لماذا تتوقع أن تنجح الفكرة وما الدليل المتاح، مثل نتيجة سابقة أو سؤال متكرر. هذا تبرير للاختبار وليس نتيجة أداء تحققت.','content-brief')
rule('الناتج الخام من الوكيل (اختياري)','احتفظ برد الوكيل الأصلي عند الحاجة للمراجعة. لا تضع فيه كلمة مرور أو بيانات مرضى، وراجع الحقول المنظمة التي سيعتمد عليها التنفيذ.','content-brief')
rule('العنوان','اكتب عنوانًا يميز المادة أو السجل في هذه الشاشة. في المحتوى هو عنوان الفكرة، وفي بيانات المركز هو عنوان المكان. اتبع اسم النموذج قبل الحفظ.','content')
rule('نص المحتوى','اكتب الفكرة والنص المطلوب مراجعتهما. رتّب الرسالة وأضف المراجع الطبية في حقول المصادر، ثم أرسل للمراجعة حسب المرحلة.','content')
rule('التخصص|التخصص / القسم|القسم|فلترة المؤشرات بتخصص معيّن','اختار التخصص أو القسم الذي تخصه الخدمة أو المادة أو التقرير. في الفلترة يغيّر العرض فقط، وفي الحجز يؤثر على ترشيح الطبيب المطابق للقسم.','content')
rule('اسم المصدر','اكتب اسم الجهة أو المجلة التي نشرت المرجع، مثل هيئة صحية أو مجلة علمية. لا تكتب اسمًا من غير مصدر موجود يمكن مراجعته.','medical-sources')
rule('عنوان الصفحة أو الدراسة','انقل عنوان الصفحة أو الدراسة التي تدعم المعلومات المستخدمة، حتى يقدر المراجع يطابقها مع الرابط.','medical-sources')
rule('الرابط (https)|رابط المصدر أو مرجعه','ضع رابط المرجع الفعلي أو بياناته التي تسمح بالرجوع إليه. رابط الصفحة العامة للجهة وحده قد لا يدعم المعلومة المحددة.','medical-sources')
rule('النص الذي يظهر على التصميم (يُترك فارغًا لو المحتوى غير طبي)','اكتب اسم المصدر بصيغة قصيرة مناسبة للتصميم بعد التأكد من المرجع. اترك الحقل فارغًا إذا كانت المادة غير طبية وفق تعليمات النموذج.','medical-sources')
rule('نص المصدر أو ملخصه','ضع النص أو الملخص الذي يعتمد عليه المحتوى، مع المرجع في حقله. حافظ على المعنى وراجع نقل الأرقام دون اختلاق معلومة غير واردة.','medical-sources')
rule('نوع الطلب|نوع المحتوى|أسلوب المحتوى|نوع الإجراء','اختار من القائمة نوع العمل المقصود في عنوان النموذج. النوع يحدد الحقول والخطوات التالية، فراجعه قبل ملء المبالغ أو إرسال الطلب.','content')
rule('الجمهور','حدد لمن تُكتب الرسالة، مثل مرضى بالغين أو أولياء أمور، حتى تتوافق اللغة والتفاصيل مع القارئ المقصود.','content-brief')
rule('القالب|قالب التصميم|تنويعة التصميم','اختار تخطيط القالب المناسب للمحتوى، ثم راجع المعاينة والحقول التي يتيحها. تغيير القالب قد يغيّر أماكن النصوص والصور.','design-guide')
rule('نسخة اللوجو','اختار نسخة الشعار التي تتناسب مع الخلفية، ثم تأكد أنه واضح داخل المعاينة. لا تستبدل هوية صفحة بهوية صفحة أخرى.','design-guide')
rule('العنوان الرئيسي — حتى ٥ كلمات|عنوان الكفر','اكتب عنوانًا يصلح للقراءة داخل التصميم أو الكفر. التزم بالحد المكتوب بجوار الحقل، وراجع ألا يخرج النص عن مساحته.','design-guide')
rule('عنوان ثانوي','اكتب السطر المكمل للعنوان الرئيسي إذا احتاج التصميم توضيحًا. يمكن تركه فارغًا إذا لم تكن له حاجة وكان الحقل اختياريًا.','design-guide')
rule('السطر التوضيحي — حتى ٨ كلمات|السطر التوضيحي','اكتب شرحًا قصيرًا يكمل العنوان داخل التصميم، والتزم بعدد الكلمات إن وُجد. هذا السطر لا يحل محل الكابشن.','design-guide')
rule('ترتيب السطرين|وضع العنوان|مكان العنوان','اختار ترتيب النص ومكانه حسب المعاينة. راجع عدم تغطية الصورة أو الشعار وعدم خروج السطر خارج حدود التصميم.','design-guide')
rule('عرض منطقة النص بالبكسل','عرض المساحة المسموح للنص أن يلتف داخلها بالبكسل. زيادته توسع السطر، وتقليله يوزع الكلام على سطور أكثر.','design-guide')
rule('حجم خط العنوان بالبكسل|حجم خط السطر التوضيحي بالبكسل|حجم خط زر التفاعل بالبكسل|حجم العنوان الثانوي|حجم نص التصميم','اكتب أو حرّك حجم الخط بالبكسل للعنصر المذكور فقط. راجع المعاينة بعد التعديل حتى لا يتداخل النص أو يُقص.','design-guide')
rule('الدكتور أو الدكتورة|اختر الطبيب|الطبيب|الطبيب / مقدم الخدمة|الطبيب المعالج|الطبيب المنفذ','اختار الطبيب الذي يخصه الإجراء فعلًا. في الحجز يلزم تطابق القسم وعقد مؤهل وتواجد، وفي التنفيذ يسجل الطبيب الذي قدم الخدمة.','doctor-missing')
rule('اسم الدكتور|اسم الطبيب|اسم الطبيب الموقّع','اكتب الاسم المعتمد للطبيب كما سيظهر في التصميم أو التقرير أو العقد. لا تستخدم اسم موظف بديلًا عن الطبيب المسؤول عن المستند.','design-guide')
rule('التايتل والتخصص','اكتب الصفة المهنية والتخصص المعتمدين للطبيب كما سيظهران على التصميم، دون إضافة مؤهل أو لقب غير مثبت.','design-guide')
rule('حجم الاسم الأقصى|حجم التايتل الأقصى','حدد أكبر حجم خط مسموح للاسم أو الصفة في المعاينة. راجع الأسماء الطويلة حتى تظل داخل المنطقة المخصصة.','design-guide')
rule('أيام العمل','حدد الأيام التي تخص جدول الطبيب أو التصميم حسب المواعيد المعتمدة. هذا النص في التصميم لا ينشئ تواجدًا في جدول الحجز.','design-guide')
rule('من الساعة|حتى الساعة','حدد بداية أو نهاية الفترة وفق المواعيد المقصودة. عند تجهيز تصميم مواعيد راجعها مع الجدول، فهي لا تعدل جدول الحجز تلقائيًا.','design-guide')
rule('تكبير صورة الدكتور|تكبير أو تصغير الصورة|تكبير الصورة|تكبير صورة بعد','تحكم في تكبير الصورة داخل إطارها، وليس أبعاد الملف النهائي. راجع ألا يُقص الوجه أو الجزء المطلوب من الصورة.','design-guide')
rule('تحريك داخل الدائرة يمينًا ويسارًا|تحريك داخل الدائرة فوق وتحت|موضع أفقي|تحريك صورة قبل أو الديكوبيه يمينًا ويسارًا|تحريك صورة بعد يمينًا ويسارًا|تحريك صورة بعد فوق وتحت|مكان الصورة يمين/شمال|مكان الصورة فوق/تحت','حرّك الصورة داخل الإطار في الاتجاه المذكور، ثم راجع المعاينة. الحركة لا تغير بيانات الصورة الأصلية أو معنى الحالة.','design-guide')
rule('صورة من جهازك|صورة بعد|الصورة (تقدر تاخد لقطة من الفيديو)|نوع الصور|اختيار الملفات|اختيار الملف|رفع ملف لهذا المشهد|نوع الملف','اختار نوع الملف أو ارفع الملف المطلوب للعنصر المذكور. راجع أنه يخص المادة والصفحة وله إذن استخدام، ثم تحقق من ظهور المعاينة.','design-guide')
rule('وصف المشهد|وصف اللقطة المطلوبة','صف الأشخاص والمكان والحركة والإضاءة المطلوبة للمشهد. استخدم وصفًا محددًا دون بيانات مرضى أو طلب تمثيل نتيجة علاج غير موثقة.','video-guide')
rule('الجودة|النموذج','اختار جودة أو نموذج التوليد المتاح. راجع التكلفة المتوقعة والميزانية قبل بدء التوليد، ثم افحص الناتج قبل اعتماده.','video-guide')
rule('بداية الـFade|نهاية الـFade|طول الفيد بالبكسل','حدد منطقة التلاشي التي تمزج الصورة بالخلفية. راجع تدرج الانتقال في المعاينة حتى لا يخفي النص أو تفاصيل الصورة.','design-guide')
rule('نص داخل التصميم — للقوالب ١ إلى ٥','اكتب النص الذي سيُرسم داخل القالب المحدد. راجع عدد الكلمات وفواصل السطور في المعاينة؛ هذا ليس كابشن النشر.','design-guide')
rule('خلفية قالب التجميل|لون خلفية التجميل|خلفية الصورة المولّدة','اختار الخلفية المناسبة للهوية ونوع القالب، ثم راجع تباين النص وحدود الصورة.','design-guide')
rule('كود HEX','اكتب كود لون بصيغة مثل #0F369D. الكود يحدد لون العنصر، وراجع الهوية والتباين في المعاينة.','design-guide')
rule('نوع اللون','اختار لونًا ثابتًا أو تدرجًا حسب الخيارات. التدرج يحتاج ألوانًا واتجاهًا مناسبين للعنصر.','design-guide')
rule('زاوية الجريدينت بالدرجات|زاوية جريدينت العنوان','زاوية اتجاه التدرج بالدرجات، وليست دوران النص نفسه. راجع بداية اللون ونهايته في المعاينة.','design-guide')
rule('لون العنوان الرئيسي','اختار لون العنوان الرئيسي مع الحفاظ على وضوحه فوق الخلفية وهوية الصفحة.','design-guide')
rule('ظهور الكتلة|قوة اللون %','تحكم في ظهور الكتلة أو قوة اللون حسب النسبة المعروضة. راجع النتيجة في المعاينة قبل التصدير.','design-guide')
rule('طول الكتلة بالبكسل','حدد امتداد كتلة اللون بالبكسل في التصميم، ثم راجع عدم تغطية النص أو الصورة.','design-guide')
rule('اتجاه التوسيع','اختار الجهة التي ستُستكمل فيها الصورة عند توسيعها. راجع الحدود والأجزاء المضافة قبل استخدام الناتج.','design-guide')
rule('المعلومات الحالة أو الرسالة|معلومات الحالة أو الرسالة','اكتب سياق المادة أو الرسالة المراد شرحها، مع بيانات عامة وإذن استخدام الصور. لا تضف هوية مريض في توجيه التوليد.','design-guide')
rule('عدد الشرايح','حدد عدد شرائح الكاروسيل المطلوب. طابق العدد مع النص والفكرة وراجع ترتيب البداية والنهاية.','carousel-guide')
rule('أسلوب الكاروسيل','اختار طريقة عرض الفكرة على الشرائح حسب القالب المتاح، ثم راجع ترابط الرسالة بينها.','carousel-guide')
rule('نص كل شريحة (اختياري — سطر لكل شريحة، أو سيبه فاضي والوكيل يكتبه)','اكتب كل شريحة في سطر منفصل بالترتيب. إذا تركته فارغًا وفق الاختيار، سيجهز الوكيل النص وتراجعه قبل الاعتماد.','carousel-guide')
rule('كلمة التصنيف (فوق العنوان)','اكتب التصنيف القصير الذي يظهر أعلى عنوان الكفر، مثل اسم السلسلة أو نوع المحتوى.','design-guide')
rule('الكلمة الملوّنة في العنوان','اكتب الكلمة من العنوان التي تريد إبرازها بلون مختلف. راجع أن نفس الكلمة موجودة في نص العنوان.','design-guide')
rule('طريقة الإنتاج','اختار المسار المطلوب لإنتاج المادة مثل استخدام ملفات مرفوعة أو التوليد حسب القائمة. راجع ما يتطلبه كل مسار قبل البدء.','video-guide')
rule('موسيقى الفيديو','اختار إعداد الموسيقى المتاح، وراجع مستوى الصوت وحق الاستخدام وألا تطغى على التعليق الصوتي.','video-guide')
rule('الانتقالات|الانتقال بين الصور','اختار طريقة الانتقال بين المشاهد، ثم راجع توقيتها مع الصوت والمدة.','video-guide')
rule('حركة الصور|حركة الصورة','اختار حركة الصورة داخل المشهد مثل التكبير أو التحريك إن كان متاحًا. راجع ألا تقص الجزء المطلوب.','video-guide')
rule('مصدر المشاهد|مصدر المشهد','اختار هل المشهد من ملفاتك أو صورة أو فيديو مولد حسب الخيارات. كل مصدر يحتاج مدخلاته قبل الإنتاج.','video-guide')
rule('إطار مقطع الفيديو','حدد طريقة احتواء الفيديو داخل الإطار، وراجع القص والمساحات الفارغة في المعاينة.','video-guide')
rule('بداية مقطع الفيديو بالثواني','اكتب الثانية التي تريد بدء الجزء المستخدم عندها من الفيديو المرفوع، مثل 5. لا تتجاوز مدة الملف.','video-guide')
rule('مدة المقطع المولد|مدة اللقطة','حدد مدة اللقطة حسب خيارات التوليد، ثم راجع اتساقها مع مدة الصوت والمشهد.','video-guide')
rule('الحد الشهري (ج.م)|الميزانية الشهرية بالدولار','حدد سقف ميزانية التوليد للشهر بالعملة المكتوبة في الحقل. هذا حد رقابي للتكلفة، ولا يضيف رصيدًا لحساب مزود الخدمة.','video-guide')
rule('سعر الدولار (ج.م)','اكتب سعر التحويل المستخدم لحساب تكلفة التوليد بالجنيه لكل دولار وفق سياسة المركز. هذا إعداد تكلفة وليس سعر بيع خدمة للمريض.','video-guide')
# Patient records: these instructions describe documentation, not diagnosis or treatment advice.
rule('الاسم بالكامل|الاسم زي ما هيتطبع','اكتب اسم المريض بعد مطابقته مع ملفه ومستنده. راجع تهجئة الاسم قبل حفظ أو طباعة التقرير؛ لا تنشئ ملفًا ثانيًا لتصحيح حرف.','patient-records')
rule('رقم الهاتف|رقم الهاتف|تليفون المركز|واتساب','اكتب رقم التواصل الصحيح مع كود الدولة إذا طلبه النموذج. راجع صاحب الرقم والغرض منه، فقد تستخدم الأسرة رقمًا واحدًا لأكثر من مريض.','patient')
rule('البريد الإلكتروني|الإيميل','اكتب عنوان البريد بصيغته مثل name@example.com حسب صاحب السجل. راجع صحته قبل الحفظ لأنه قد يستخدم للتواصل أو الدخول.','access')
rule('الرقم القومي (اختياري)','سجل رقم الهوية للمريض الصحيح عند وجوده وفق صلاحية النموذج. لا تستخدم رقمًا وهميًا لإكمال الحقل ولا تضع رقم ولي الأمر بدل المريض.','patient-records')
rule('السن','اكتب عمر المريض بالوحدة المطلوبة في النموذج، ولا تستخدم تاريخ الزيارة أو رقم الملف بدل العمر. راجع توافقه مع تاريخ الميلاد إن كان مسجلًا.','patient-records')
rule('النوع','اختار النوع الصحيح للسجل وفق قائمة النموذج. في ملف المريض المقصود بيانات المريض، وفي طلب مالي المقصود نوع العملية.','patient-records')
rule('الرقم الطبي|الرقم الطبي (اختياري)','اكتب الرقم الطبي الخاص بالمريض وفق سجلات المركز. يختلف عن رقم الهوية وعن رقم زيارة منفردة. ابحث عن الملف الموجود قبل إضافة رقم جديد.','patient-records')
rule('جهة التعاقد (اختياري)|جهة التعاقد لهذه الزيارة','اختار الجهة التي ينطبق عقدها على المريض أو الزيارة المعنية، وراجع سريان العقد وأهلية الخدمة قبل استخدام سعر التعاقد.','entities')
rule('تاريخ آخر زيارة','سجل تاريخ آخر زيارة فعلية وفق الملف، وليس تاريخ تحديث البيانات. راجعه مع الزيارات المسجلة.','patient-records')
rule('الأمراض المزمنة|الحالة المزمنة|هل تعاني من أمراض مزمنة؟|أمراض مزمنة','سجل الأمراض المعروفة كما أفاد المريض أو أثبتها الطبيب مع التفاصيل المتاحة. لا تحول عرضًا غير مشخص إلى مرض مؤكد.','patient-records')
rule('العمليات الجراحية','سجل العمليات السابقة وتواريخها إن توفرت وفق الإفادة أو المستند. إذا لم تتوفر المعلومة فوضّح ذلك حسب النموذج.','patient-records')
rule('تاريخ مرضي بالعائلة','سجل الحالات العائلية ذات الصلة كما وردت في الإفادة، مع صلة القرابة إن كانت معلومة، دون وضعها كتشخيص للمريض.','patient-records')
rule('تاريخ الزيارة','حدد تاريخ الزيارة الطبية التي تخصها البيانات. تعديل السجل اليوم لا يغيّر تاريخ الزيارة الأصلية تلقائيًا.','patient-records')
rule('الشكوى|الشكوى (Chief Complaint)|سبب الزيارة|سبب الحضور والشكوى الأساسية|المشكلة الأساسية|الأعراض أو المشكلة الحالية','دوّن سبب حضور المريض وأعراضه بلغته مع البداية والمدة إذا توفرت. هذا وصف للشكوى، أما التشخيص فيسجله المختص في حقله.','patient-records')
rule('ضغط الدم','سجل قراءة ضغط الدم التي قاسها المختص كما هي بوحدة النموذج، مع الانقباضي والانبساطي عند طلبهما. لا تدخل قراءة تقديرية أو قيمة لتجاوز الحقل.','patient-records')
rule('سكر الدم','سجل نتيجة القياس الفعلية ووحدتها ووقت/حالة القياس إن طلبها النموذج، مثل صائم أو عشوائي. لا تضع تشخيصًا أو تعدل النتيجة بالتخمين.','patient-records')
rule('النبض','سجل معدل النبض المقاس بالدقيقة وفق الفحص. اترك غير المقاس وفق قواعد النموذج بدل تسجيل صفر كأنه نتيجة.','patient-records')
rule('الوزن','سجل الوزن المقاس بالكيلوجرام حسب النموذج وتاريخ القياس. لا تستخدم الوزن المستهدف بدل الوزن الحالي.','patient-records')
rule('الطول','سجل الطول المقاس بالسنتيمتر حسب النموذج، مثل 170. راجع الوحدة قبل حساب أي مؤشر مشتق منه.','patient-records')
rule('نسبة الأكسجين','سجل نسبة تشبع الأكسجين المقاسة كما ظهرت في جهاز القياس، مع تفاصيل القياس عند طلبها. هذه خانة توثيق وليست تفسيرًا للنتيجة.','patient-records')
rule('نسبة الدهون','سجل النسبة المقاسة وتاريخها وفق النموذج والطريقة المتاحة. لا تستخدم الوزن بالكيلوجرام مكان النسبة المئوية.','patient-records')
rule('خطة الأدوية|الأدوية|الروشتة|ملاحظات دوائية إضافية|أدوية نفسية سابقة أو حالية','انقل خطة الطبيب أو قائمة الأدوية الموثقة مع الاسم والتركيز والجرعة والتكرار والمدة في حقولها. لا تقترح جرعة أو تستنتج علاجًا من الشكوى.','patient-records')
rule('الأشعة|التحاليل|توصيات أخرى','سجل طلب الطبيب أو التوصية المعتمدة، واربط المستند إن توفر. طلب الفحص يختلف عن رفع نتيجة الفحص أو تفسيرها.','patient-records')
rule('تاريخ المتابعة|يوم المتابعة|وقت المتابعة|موعد الجلسة القادمة','حدد موعد المتابعة المتفق عليه بالتاريخ والوقت في حقليهما. راجع جدول الحجز إن كان مطلوبًا حجز موعد فعلي؛ كتابة توصية متابعة لا تحجزه وحدها.','patient-records')
rule('في حالة تأجيل الموعد، اختر السبب','اختار السبب الذي أدى لتأجيل المتابعة فعلًا من القائمة، وسجل التفاصيل المطلوبة قبل تأكيد التعديل.','patient-records')
rule('كل|وحدة|لمدة|البداية|الساعة','هذه خانات تكرار أو توقيت بحسب النموذج. في جدول دواء انقل عدد الفواصل ووحدتها والمدة وبداية الخطة والساعة من تعليمات الطبيب. وفي تكرار مهمة انقل إعداد التكرار المطلوب، ولا تستخدم نفس القيم للسياقين.','patient-records')
rule('الفئة','اختار تصنيف السجل حسب الشاشة. في رفع مستند مريض مثل أشعة أو تحاليل أو تقرير، وفي المخزن تصنيف الصنف. التصنيف يساعد الفلترة ولا يغير محتوى الملف.','patient-records')
rule('الملف','اختار المستند الذي يخص السجل والمريض الصحيحين، وراجع اسمه وامتداده قبل الرفع. رفع الملف يحفظ مرفقًا ولا يعني اعتماد محتواه.','patient-records')
rule('تاريخ إصدار المستند (اختياري)|تاريخ التقرير|تاريخ الروشتة|تاريخ الطلب','اكتب التاريخ الموجود على المستند أو الطلب المعني، وليس تاريخ رفع الملف إذا كان مختلفًا.','patient-records')
rule('ملاحظات / تفاصيل الملف (اختياري)','اكتب وصفًا يساعد على تمييز المرفق، مثل نوع الفحص وتاريخه، دون تكرار بيانات حساسة لا يحتاجها الوصف.','patient-records')
rule('التخصص (اختياري — لتمييز التقارير لو أكتر من تقرير لنفس المريض)|التخصص (اختياري)','حدد تخصص التقرير أو الطبيب حتى يمكن تمييزه عن تقارير المريض الأخرى. اتركه فارغًا إذا كان اختياريًا وغير معروف.','patient-records')
rule('نص التقرير|Summary|Conclusion','انقل نص التقرير أو ملخصه أو خلاصة الطبيب في الخانة المقابلة. راجع مصدر النص والطبيب والتاريخ، ولا تكتب استنتاجًا طبيًا بدل المستند.','patient-records')
rule('التشخيص (اختياري)|التشخيص المبدئي (اختياري)|Diagnosis (تشخيص الحالة بشكل عام)|التشخيص (الحالة اللي الجدول ده مناسب لها)','سجل التشخيص الذي وثقه المختص، وميّز المبدئي من المعتمد حسب عنوان الحقل. لا تستنتج تشخيصًا لإكمال النموذج.','patient-records')
rule('Others (اختياري)','اكتب الفحص أو الطلب الإضافي الذي حدده الطبيب ولم تجده ضمن الخيارات. لا تكرر فحصًا سبق اختياره في القائمة.','patient-records')
rule('كومنت العميل (اختياري)','سجل تعليق المريض أو العميل كما ورد مع الحفاظ على معناه. ميّزه عن ملاحظة الطبيب أو تشخيصه.','patient-records')
rule('Referred By','اسم الطبيب أو الجهة التي أحالت المريض كما ورد في مستند الإحالة. لا تستخدم اسم من سجل البيانات بدل جهة الإحالة.','patient-records')
rule('Dimensions','سجل القياسات المطلوبة في التقرير مع وحداتها حسب الفحص ونتيجته الأصلية. لا تضع وصفًا عامًا مكان القياسات أو تحول الوحدات بالتخمين.','patient-records')
rule('صور الأشعة المرفقة (عدد مفتوح — اختار كذا صورة مرة واحدة)|أشعة الأسنان المرفقة (عدد مفتوح — اختار كذا صورة مرة واحدة)|صور أشعة/فحوصات مرفقة (عدد مفتوح — اختار كذا صورة مرة واحدة)|مستندات مرفقة','ارفع الصور أو المستندات التي تخص هذا التقرير والمريض. يمكنك تحديد عدة ملفات إذا سمح الحقل. راجع وضوح الصور وتاريخها قبل الحفظ.','patient-records')
rule('علاج الأسنان السابق','سجل إجراءات الأسنان السابقة ذات الصلة كما وردت في الملف أو إفادة المريض، مع التواريخ المتاحة.','patient-records')
rule('خطة العلاج المقترحة|الهدف من العلاج','سجل الخطة أو الهدف الذي حدده المختص بعد التقييم، وليس وعدًا بنتيجة مؤكدة. راجع ربطها بالزيارة والجلسات المعنية.','patient-records')
rule('التركيبة (ثابتة / متحركة)','سجل نوع التركيبة المعتمد في خطة الأسنان والموضع والتفاصيل إن طلبها النموذج. لا تختار نوعًا بدل قرار الطبيب.','patient-records')
rule('مخطط الأسنان (اضغط على السن لتحديد مكانه)','اختار السن أو الموضع الذي حدده طبيب الأسنان على الرسم، ثم سجل الإجراء أو الملاحظة المطلوبة. راجع الجهة والرقم قبل الحفظ.','patient-records')
rule('جدول الجلسات','أدخل الجلسات المعتمدة وترتيبها وتواريخها وحضورها حسب الخطة. الجدول الطبي يختلف عن التحصيل أو إثبات تنفيذ خدمة مالية.','patient-records')
rule('نقاط الألم (اضغط على الرسم لتحديد مكان الألم)','حدد المواضع التي وصفها المريض أو سجلها المختص على الرسم، مع الجهة والدرجة إن طلبهما النموذج. الرسم توثيق لمكان الألم ولا يثبت تشخيصًا.','patient-records')
rule('اسم الجدول','اكتب اسمًا يميز قالب أو جدول الخطة، مثل اسم خطة وجبات أو جلسات. لا تضع رقم ملف مريض كاسم لقالب مشترك.','patient-records')
rule('الوجبات|جدول الوجبات (Daily Meals)','انقل الوجبات والكميات والتوقيتات من خطة أخصائي التغذية في صفوفها. راجع أن الخطة تخص الزيارة الحالية قبل حفظ نسخة المريض.','patient-records')
rule('التوقيت','اكتب توقيت الزيارة أو الوجبة حسب عنوان النموذج. راجع هل الحقل يطلب ساعة أم تاريخًا مع ساعة قبل الحفظ.','patient-records')
rule('تاريخ أول جلسة','اكتب تاريخ بداية الجلسات الفعلية أو المتفق عليها حسب النموذج، وليس تاريخ إنشاء الملف إذا كان مختلفًا.','patient-records')
rule('متى بدأت المشكلة؟','سجل تاريخ أو عمر بداية المشكلة كما أفاد المريض أو ولي الأمر، ووضّح إذا كانت البداية تقريبية.','patient-records')
rule('نوع المشكلة','حدد تصنيف المشكلة من اختيارات التقييم حسب ما سجله المختص. استخدم التفاصيل لتوضيح الاختيار بدل اختيار تشخيص غير مؤكد.','patient-records')
rule('تفاصيل أخرى|تفاصيل تدخل آخر','اكتب التفصيل الذي لا تغطيه الخيارات في هذا الجزء من التقييم، مع توضيح ما حدث أو التدخل الذي وثقه المختص.','patient-records')
rule('هل يوجد تاريخ زواج أقارب؟|هل يوجد أمراض أو اضطرابات وراثية بالعائلة؟|هل حدثت مشاكل أثناء الحمل أو الولادة؟','سجل الإجابة من إفادة ولي الأمر أو المستند، ثم التفاصيل المتاحة. عدم معرفة المعلومة لا يساوي إجابة «لا».','patient-records')
rule('تطور الكلام واللغة: أول كلمة|أول جملة','سجل العمر أو التاريخ الذي ظهرت فيه أول كلمة أو جملة حسب إفادة ولي الأمر، مع توضيح التقريب أو عدم المعرفة.','patient-records')
rule('هل سبق له جلسات تخاطب؟|هل سبق علاج أو جلسات؟','سجل وجود علاج أو جلسات سابقة مع النوع والمدة والنتيجة الموثقة إن توفرت، دون اعتبارها خطة الجلسة الحالية.','patient-records')
rule('مستوى الفهم والكلام حاليًا','سجل ملاحظات التقييم الحالي كما وثقها أخصائي التخاطب، مع أمثلة إن لزم. لا تستنتج مستوى من السن وحده.','patient-records')
rule('الهدف من الجلسات|أهداف الجلسة|هدف الجلسة','سجل الهدف الذي يعمل عليه المختص في الخطة أو هذه الجلسة تحديدًا، بحيث يمكن مقارنة التنفيذ والاستجابة لاحقًا.','patient-records')
rule('ملاحظات الأخصائي','سجل الملاحظات المهنية التي وثقها المختص وربطها بتاريخ التقييم أو الجلسة. ميّزها عن إفادة ولي الأمر.','patient-records')
rule('عدد الجلسات المخطط لها','اكتب عدد الجلسات المعتمدة في الخطة، وليس عدد الجلسات التي حضرها المريض بالفعل أو عدد الدفعات.','patient-records')
rule('الجلسة|رقم الجلسة','اكتب ترتيب الجلسة داخل الخطة الطبية حسب التسلسل المسجل. هذا يختلف عن رقم ملف المريض وعن رقم إيصال السداد.','patient-records')
rule('موعد الجلسة','حدد تاريخ ووقت الجلسة المقصودة وراجع التواجد والحجز إذا لزم. التسجيل في التقرير وحده لا يؤكد موعدًا في نظام الحجز.','patient-records')
rule('مدة الجلسة','سجل المدة المطلوبة بوحدة الحقل. عند توثيق جلسة منفذة اكتب مدتها الفعلية بدل مدة الخطة إذا اختلفتا.','patient-records')
rule('مستوى الاستجابة|مستوى التحسن','اختر التقييم الذي سجله المختص لهذه الجلسة مع دليل أو ملاحظة تفسره. لا تستخدم التقييم كضمان لنتيجة مستقبلية.','patient-records')
rule('ما تم التدريب عليه|التدخل المستخدم','سجل الأنشطة أو التدخلات التي نفذها المختص بالفعل في الجلسة. ميّز بين المنفذ وبين المخطط للجلسة القادمة.','patient-records')
rule('الواجب المنزلي','دوّن التدريب أو التعليمات المنزلية التي اعتمدها المختص بصيغتها، مع التكرار والمدة إذا حددهما.','patient-records')
rule('حضور الجلسة','اختر حالة الحضور الفعلية مثل حضر أو غاب حسب النموذج. لا تعتبر مجرد الحجز حضورًا أو جلسة منفذة.','patient-records')
rule('نوع الجلسة|نوع الزيارة / الخدمة|نوع الزيارة','حدد نوع الزيارة أو الجلسة التي يوثقها هذا السجل وفق القائمة، ثم أكمل النموذج المناسب لها.','patient-records')
rule('سبب الحجز','اكتب سبب طلب الموعد أو الجلسة كما ورد، مع تمييزه عن تشخيص المختص بعد التقييم.','patient-records')
rule('أهم الضغوط أو الظروف الحالية|تأثير المشكلة على الحياة','وثق ما وصفه المريض عن الظروف الحالية أو تأثير الأعراض على حياته في حدود التقييم المطلوب. سجل وقائع وإفادة، ولا تضف تفسيرًا غير موثق.','patient-records')
rule('التزام العميل','سجل الالتزام الذي تم ملاحظته أو الإبلاغ عنه بالخطة أو الواجبات، مع ملاحظة توضح الأساس بدل تقييم بلا دليل.','patient-records')
rule('خطة الجلسة القادمة','سجل الخطوات التي حددها المختص للجلسة التالية بعد مراجعة ما نُفذ واستجابة المريض. هذه خطة وليست إثبات تنفيذ.','patient-records')

rule('الخزينة|اسم الخزينة','اختر الخزينة التي تخص المبلغ والمكان ونوع الحركة، أو اكتب اسمًا يميز الخزينة عند إنشائها. راجع صلاحيتها للاستلام أو الصرف والوردية المرتبطة.','cash-shifts-guide')
rule('وردية الاستقبال المفتوحة|وردية الكاش أو الفيزا|الوردية النقدية|وردية الكاش','اختر وردية مفتوحة للمستخدم والخزينة المناسبة. الكاش والفيزا يحتاجان وردية بحسب المسار، وعدم ظهور وردية لا يعالج بإدخال معرّف يدوي.','cash-shifts-guide')
rule('حد النثريات للإذن','أقصى مبلغ يسمح به حد النثريات لهذا النوع من الصرف حسب الإعداد. الحد لا يضيف كاشًا للخزينة ولا يغني عن وجود رصيد واعتماد.','cash-shifts-guide')
rule('حركات الخزينة|نوع الحركة','حدد هل الخزينة تستلم فقط أو تصرف فقط أو الاثنين حسب خياراتها. التحصيل والصرف يجب أن يتوافقا مع هذا الإعداد.','cash-shifts-guide')
rule('ملاحظات الجرد|ملاحظة الفروق|نتيجة المراجعة وتفسير الفرق','دوّن نتيجة العد والفرق بين الفعلي والدفتر وسبب الفرق أو ما يحتاج مراجعة. الفرق لا يثبت وحده مسؤولية موظف ولا يتحول تلقائيًا لخصم راتب.','cash-shifts-guide')
rule('الكاش المعدود فعليًا','اكتب النقد الموجود بعد العد الفعلي بالجنيه، لا الرصيد الذي تتوقعه من الشاشة. النظام يقارن العد بالحركات لإظهار الفرق للمراجعة.','cash-shifts-guide')
rule('الإقفال حتى تاريخ','حدد آخر تاريخ تريد إقفاله محاسبيًا بعد مراجعة العمليات. الإقفال قد يمنع قيودًا أو تصحيحات داخل الفترة، فلا تستخدم تاريخًا مستقبليًا لإخفاء فرق.','ledger-guide')
rule('المبلغ بالجنيه|القيمة بعد الخصم بالجنيه','اكتب قيمة هذه العملية بالجنيه بعد مراجعة المستحق أو المبلغ المعتمد. إذا كان سدادًا جزئيًا أدخل الجزء المدفوع فقط، ولا تكرر تحصيلًا سبق تسجيله.','collections')
rule('قيمة الخدمة بعد الخصم دون المستلزمات|سعر الخدمة (بدون مستلزمات)','اكتب قيمة الخدمة نفسها بعد الخصم وفق المستند، مع استبعاد المستلزمات التي لها بنود مستقلة. راجع ألا تحتسب نفس المستلزم داخل الخدمة وخارجها مرتين.','invoice')
rule('رقم الإيصال أو مرجع العملية|رقم الإيصال / مرجع العملية|مرجع إيصال / تحويل فريد|مرجع السداد أو التحويل','اكتب رقم الإيصال أو مرجع التحويل الفعلي الذي يميز الدفعة، وراجع عدم استخدام نفس المرجع لتسجيل دفعة مكررة.','collections')
rule('مرجع الفاتورة|مرجع الفاتورة من نظام المركز','اكتب مرجع الفاتورة الأصلية التي تمثل الخدمة في نظام المركز كما هو. لا تستخدم رقم إيصال تحصيل أو رقم مريض بدل رقم الفاتورة.','invoice')
rule('مرجع المريض|مرجع المريض فقط|مرجع المريض الذي سيُستخدم على الفاتورة|معرف الملف المختار','اختر أو انقل مرجع ملف المريض المقصود من سجله وفق النموذج. طابق رقم الملف والاسم، ولا تضع اسمًا حرًا إذا كان الحقل يطلب معرّف الملف.','patient')
rule('رقم ملف المريض|رقم ملف التجربة','اكتب رقم الملف المقصود حسب مساحة التشغيل. ملف التجربة منفصل عن الأرشيف الحقيقي، ورقم الملف يختلف عن الهاتف وعن رقم الزيارة.','patient')
rule('الخدمة المستحقة|الخدمة غير المحصلة|الفاتورة وحصة غير محصلة|فاتورة الخدمة المنفذة','اختر مستند الخدمة أو الفاتورة الذي توجد عليه المديونية أو الحصة المطلوبة فعلًا. راجع المريض والمبلغ المتبقي قبل ربط التحصيل أو المعالجة به.','invoice')
rule('الفاتورة|الزيارة','اختر الفاتورة أو الزيارة المرتبطة بالمريض والإجراء الحالي. راجع الرقم والتاريخ، ولا تربط مستلزمًا أو دفعة بزيارة أخرى لنفس المريض.','invoice')
rule('التحصيل الأصلي للاسترداد','اختر إيصال التحصيل الذي سيتم رد جزء منه أو كله. حدود الاسترداد تعتمد على الأصل وما سبق رده، وليس على المبلغ المكتوب في طلب جديد وحده.','requests')
rule('الخدمة المطلوب إلغاؤها','اختر الخدمة التي ستلغيها فعلًا، وراجع هل نُفذت أو حُصلت قبل طلب الإلغاء لأن الأثر المالي يختلف حسب الحالة.','requests')
rule('سبب الطلب|سبب الاسترداد|سبب الطلب / بيان المستند|السبب|السبب (مطلوب)|شرح المستند وسبب العملية|السبب والمستند','اكتب الحدث الذي يستدعي الطلب وسببه والمستند الذي يثبته، مثل رد دفعة عن موعد ملغي. لا تكتب سببًا عامًا لا يسمح للمراجع بفهم العملية.','requests')
rule('مرجع مستند الصرف أو التمويل أو الاسترداد|مرجع الاستخدام / الاسترداد|مرجع المستند|مرجع المستند الفريد|رقم المستند|مرجع التحويل / المستند','اكتب مرجع المستند الحقيقي الذي يثبت هذه العملية. إذا كان المرجع فريدًا فلا تعِد استخدامه لحدث مختلف، وراجع المستند قبل الإرسال للمراجعة.','requests')
rule('سبب القرار|سبب القرار وفحص المستند|نتيجة فحص المستند|نتيجة فحص المستند والحساب|نتيجة فحص المستند والأرصدة|سبب القرار ونتيجة المراجعة|نتيجة المراجعة والأدلة|نتيجة المراجعة والإجراء التالي','اكتب نتيجة ما راجعته ولماذا اعتمدت أو رفضت، مع الإشارة للمستند أو الفرق والإجراء التالي. المراجعة تحتاج حسابًا مستقلًا إذا اشترط المسار ذلك.','requests')
rule('حجز مرتبط — اختياري|الحجز|الحجز قبل الحضور','اختر الحجز الذي تخصه الدفعة أو الرسالة أو الإجراء. إذا كان النموذج يشترط قبل الحضور فلا تستخدم حجزًا بدأ له تنفيذ زيارة.','booking-flow')
rule('النتيجة بعد فحص القناة|دليل فحص القناة ومرجع المراجعة','سجل نتيجة فحص وسيلة التحصيل ودليلها قبل اتخاذ القرار، خصوصًا إذا كانت حالة وصول الدفعة غير مؤكدة. لا تعتبر تجهيز الرسالة أو طلب الدفع دليل تحصيل.','collections')
rule('مرجع كشف الحساب أو مستند الفحص|مرجع خطاب التأمين أو التحويل البنكي','اكتب مرجع الكشف أو خطاب الجهة أو التحويل الذي يؤيد المبلغ والمعالجة، بعد مطابقته بالمريض أو المطالبة أو الحركة المقصودة.','insurance')
rule('مرجع الرسالة أو ملاحظة الإرسال','سجل مرجع الرسالة أو ملاحظة ما حدث فعليًا بالقناة. تجهيز رسالة أو فتحها لا يثبت الإرسال أو التسليم.','communications-guide')
rule('مرجع مستند شركة التحصيل|مرجع الكشف','اكتب رقم أو اسم المستند أو فترة كشف البنك/شركة التحصيل التي ستطابقها، بحيث يمكن الرجوع لنفس المصدر لاحقًا.','bank')
rule('إجمالي العملية قبل العمولة','اكتب إجمالي التسوية قبل خصم عمولة الجهة. راجع أن الصافي المحول للبنك والعمولة يساويان الإجمالي، ولا تدخل الصافي في خانة الإجمالي.','bank')
rule('العمولة حسب المستند','اكتب مبلغ العمولة الفعلي من مستند التسوية، وليس نسبة تخمينية أو إجمالي التحصيل.','bank')
rule('الحركة الدفترية غير المطابقة','اختر القيد أو الحركة الموجودة التي تقابل سطر كشف البنك وتحتاج مطابقة. لا تسجل تحصيلًا جديدًا لمجرد أن الحركة ظهرت في الكشف.','bank')
rule('سطور الكشف: التاريخ، المرجع، المبلغ. سطر لكل حركة؛ الداخل موجب والخارج سالب.','أدخل كل حركة في سطر مستقل بصيغة التاريخ ثم المرجع ثم المبلغ كما يطلب النموذج. الداخل موجب والخارج سالب. راجع الأرصدة والفترة قبل المطابقة.','bank')
rule('تاريخ الاستحقاق حسب العقد|استحقاق المطالبة إن لزم','حدد موعد استحقاق المبلغ وفق الاتفاق أو المطالبة، وليس تاريخ التحصيل المتوقع بالتخمين أو تاريخ اليوم تلقائيًا.','insurance')
rule('مجموعة المطالبات / الشهر','اكتب مرجع الدفعة أو شهر المطالبات الذي يجمع المستندات المقصودة للتقديم والمتابعة مع الجهة.','insurance')
rule('نتيجة الاتصال أو التصحيح والمستند المرجعي|نتيجة الإجراء وأدلته','سجل ما حدث فعليًا في التواصل أو التصحيح، وما المستند الذي يؤيده، والمرحلة التالية. لا تسجل وعدًا بالسداد كأنه تحصيل.','insurance')
rule('شركة التأمين|شركة التأمين للافتتاح إن لزم','اختر الجهة صاحبة المطالبة أو الرصيد، مع مطابقة العقد والمريض والمستند. لا تجمع جهات مختلفة في افتتاح تفصيلي واحد.','insurance')
rule('سبب المعالجة وأدلتها','اكتب سبب الرفض أو التخفيض والدليل الذي يحدد نوع المعالجة. تصحيح المطالبة يختلف عن التخفيض التعاقدي وخسارة الائتمان.','insurance')
rule('الموظف المسؤول عند ثبوت مسؤوليته','اختر الموظف فقط بعد أن تثبت المراجعة مسؤوليته بالقرار والأدلة. وجود فرق نقدي وحده لا يبرر تحميله على الموظف.','cash-shifts-guide')
rule('اسم الموظف|الموظف','اختر الموظف الذي يخصه التكليف أو العقد أو الاستحقاق أو الفلترة. في مستحقات الرواتب طابق الاسم بالعقد والفترة ولا تستخدم اسم مسجل الطلب بدل المستفيد.','payroll')
rule('عقد الموظف المعتمد','اختر عقد العامل المعتمد والساري الذي يخص شهر الراتب أو الاستحقاق. وجود مسودة عقد لا يكفي لاحتساب مستحق معتمد.','payroll')
rule('الضريبة المستقطعة حسب المستند','اكتب قيمة الاستقطاع من مستند التسوية المعتمد. صافي السداد يساوي الإجمالي ناقص الاستقطاع، فلا تخصمه مرتين.','payroll')
rule('العمر الإنتاجي بالأشهر','اكتب مدة استخدام الأصل المحاسبية المعتمدة بالأشهر، مثل 60 إذا كان العمر خمس سنوات. لا تستخدم عدد أقساط شراء الأصل بدل عمره الإنتاجي.','assets-tax')
rule('تاريخ بدء التشغيل والإهلاك','حدد تاريخ بدء استخدام الأصل الذي تعتمد عليه خطة الإهلاك، وليس بالضرورة تاريخ سداد ثمنه. راجع المستند والسياسة المعتمدة.','assets-tax')
rule('عدد أشهر الإهلاك السابقة','للأصل القديم اكتب عدد الأشهر التي أُهلكت قبل إدخاله مع مراجعة تكلفة الأصل ومجمعه، حتى لا يبدأ الإهلاك من الصفر مرة أخرى.','assets-tax')
rule('الأصل المعتمد','اختر الأصل الذي اعتمدت بياناته وتخصه دورة الإهلاك أو العملية. راجع كوده وتاريخ بدء استخدامه قبل التنفيذ.','assets-tax')
rule('شهر الإهلاك التالي','حدد شهر الفترة التي سيتم حساب إهلاكها حسب تسلسل الأصل، وتأكد من عدم احتساب شهر سبق ترحيله.','assets-tax')
rule('المعالجة حسب المستند|الالتزام الضريبي المعتمد|الالتزام','اختر الالتزام الضريبي أو اتجاه المعالجة وفق المستند المعتمد، وراجع هل العملية إثبات أم سداد أم تسوية. السداد لا ينشئ نفس المصروف مرة أخرى.','assets-tax')
rule('قناة الصرف|وسيلة الصرف أو التحصيل','اختر الوسيلة المستخدمة فعليًا للمال وفق الإجراء، ثم أكمل الوردية أو مرجع التحويل المطلوب. لا تختار نقدي لعملية تمت من البنك.','collections')
rule('نوع العملية|الإجراء','حدد الإجراء أو نوع الحركة من خيارات النموذج، واقرأ أثره والمستند الذي يتطلبه قبل الحفظ أو الاعتماد. الاختيار لا ينفذ العملية وحده.','ledger-guide')
rule('الحساب','اختر الحساب المقصود من قائمة هذه الشاشة. في القيد يكون حسابًا من الشجرة، وفي الإعلانات حسابًا إعلانيًا. راجع اسم القسم وكود الحساب قبل الاختيار.','ledger-guide')
rule('صاحب الرصيد إن لزم','حدد الطرف الذي يخصه الرصيد الافتتاحي أو التفصيلي، مثل المريض أو المورد حسب الحساب. القيد التجميعي وحده لا ينشئ أرصدة تفصيلية صحيحة للأطراف.','ledger-guide')
rule('مرجع العكس الفريد|سبب العكس والمستند','اكتب مرجعًا وسببًا واضحين لعكس القيد مع مستند التصحيح. العكس يحفظ الأصل، ولا يصحح مستند تشغيل من مسار آخر تلقائيًا.','ledger-guide')
rule('سطور القيد','أدخل حساب ومبلغ كل طرف في سطره، وراجع تساوي مجموع المدين والدائن والمستند والفترة. الحفظ مسودة، والترحيل يحتاج المراجعة المطلوبة.','ledger-guide')
rule('أمر الشراء','اختر أمر الشراء المعتمد الذي ستربط به الاستلام أو الفاتورة، وطابق المورد والأصناف والكميات بدل تسجيل شراء ثانٍ لنفس الطلب.','purchases')
rule('رقم فاتورة المورد|رقم فاتورة / إيصال المورد','انقل رقم فاتورة أو إيصال المورد كما هو على المستند. هذا الرقم يربط تكلفة التوريد وحساب المورد ويختلف عن كود التشغيلة.','purchases')
rule('تاريخ فاتورة المورد','اكتب التاريخ الموجود على فاتورة المورد، وميّزه عن تاريخ إنشاء الطلب أو دفع الحساب.','purchases')
rule('رابط الفاتورة إن وجد|رابط صورة أو ملف الفاتورة إن وجد','أرفق رابط المستند المسموح الوصول إليه للمراجعين، وتأكد أنه يفتح الفاتورة المقصودة ولا يكشف ملفات أخرى.','purchases')
rule('الصرف الأصلي للمريض','اختر حركة الصرف الأصلية التي تخص المريض والصنف المراد رده، حتى يرتبط المرتجع بالمخزون والفاتورة الصحيحين.','internal-issue')
rule('الاسترداد المالي المعتمد','اختر طلب الاسترداد الذي اعتمد بالفعل ويرتبط بالعملية المراد ردها. لا تستخدم طلبًا معلقًا كدليل سداد.','requests')
rule('سبب الطلب ونتيجة الفحص','اكتب سبب المرتجع أو الطلب وما أثبته فحص الصنف والمستند، مع الكمية وحالتها عند الحاجة، ثم أرسله للمراجعة.','purchases')
rule('بند المصروف','اختر التصنيف الحقيقي للمصروف، مثل كهرباء أو مياه أو غاز أو نفايات. التصنيف يحدد عرض التكلفة في التقارير، ولا يغني عن المستند والاعتماد.','requests')
rule('عقد الطبيب لهذه الفاتورة','اختر عقد الطبيب الساري والمعتمد الذي تنطبق شروطه على الخدمة بهذه الفاتورة. إذا لم ينطبق عقد فلا تربط عقدًا آخر لمجرد إكمال النموذج.','doctor-missing')
rule('النسبة المئوية|النسبة %','اكتب النسبة فقط مثل 25 وليس مبلغ الأتعاب. تراجع النسبة مع وعاء الحساب وشروط العقد قبل الاعتماد.','doctor-missing')
rule('وعاء النسبة بعد خصم المردودات','حدد المبلغ الذي تطبق عليه نسبة الطبيب حسب العقد بعد معالجة المردودات. الخدمة دون المستلزمات تختلف عن إجمالي الفاتورة بما فيها المستلزمات.','doctor-missing')
rule('مرجع العقد أو الملحق|رقم العقد','اكتب رقم العقد أو الملحق المعتمد الذي يثبت الشروط والفترة، حتى يمكن للمراجع الرجوع لنفس الاتفاق.','doctor-missing')
rule('بداية فترة الكشف|نهاية فترة الكشف|فترة المستحقات من','حدد الفترة التي تريد استخراج مستحقاتها، وليس موعد السداد. راجع الخدمات المنفذة والعقد والفترات التي سبق تسويتها.','payroll')

rule('الصنف|الصنف من المخزن|المستلزم','اختر الصنف أو تعريف المستلزم المقصود من القائمة، وطابق الاسم والكود ووحدة الصرف. وجود اسم مشابه لا يعني أنه نفس الصنف أو أن ربط التسعير اكتمل.','supply-map')
rule('كود الصنف|كود المستلزم|الكود','اكتب كودًا يميز الصنف أو السجل داخل النظام حسب عنوان النموذج. لا تستخدم رقم فاتورة المورد أو كود تشغيلة بدل الكود الثابت للصنف.','supply-map')
rule('اسم الصنف|الاسم','اكتب اسمًا يميز السجل المقصود في عنوان النموذج. للصنف اذكر وصفًا يفرقه عن الأحجام أو المقاسات الأخرى، وتجنب إنشاء نسخة ثانية من صنف موجود.','supply-map')
rule('نوع الوحدة (علبة/زجاجة/عبوة...)','اكتب اسم وحدة التسعير مثل قطعة أو علبة أو زجاجة. الاسم ليس عدد الوحدات، ويجب أن يتوافق مع عدد محتويات العبوة ومعامل ربط المخزن.','supply-map')
rule('الكمية بوحدة الصرف|العدد','اكتب الكمية بوحدة الصرف المكتوبة للصنف، لا عدد العبوات إذا كان المخزن بالقطعة. راجع معامل التحويل قبل التأكيد.','supply-map')
rule('كمية وحدة المخزن مقابل وحدة التسعير','عدد وحدات المخزن التي تخصم لكل وحدة تسعير. قطعة مقابل قطعة = 1. علبة 100 والتخزين بالقطعة = 100. قطعة والتخزين بالعلبة100 = 0.01.','supply-map')
rule('كمية الاستهلاك الافتراضية للمريض الواحد','عدد وحدات التسعير التي تستخدم افتراضيًا لمريض واحد، مثل قطعتين. يختلف عن عدد محتويات العبوة وعن كمية وحدات المخزن لكل وحدة تسعير.','supply-map')
rule('معامل التحويل','معامل يحول كمية المصدر أو الملف المستورد إلى وحدة المخزن. راجع اتجاه التحويل المكتوب في شاشة الاستيراد قبل الاعتماد، فعبوة100 قطعة ليست قطعة واحدة.','supply-map')
rule('الحد الأدنى للمخزون','اكتب مستوى التنبيه لإعادة التوريد بوحدة المخزن. هذا حد للتنبيه وليس كمية افتتاحية أو شراء ينفذ تلقائيًا.','inventory-count')
rule('سعر بيع الوحدة للجمهور بعد هامش الربح','هذا سعر البيع للمريض للوحدة بعد إضافة الربح، وليس سعر شراء المورد. راجع أساس أعلى سعر شراء وسياسة النسبة قبل تعديله.','profit')
rule('نسبة الزيادة على تكلفة الشراء %|نسبة الإضافة على سعر الشراء %','اكتب نسبة الزيادة على تكلفة الشراء، مثل 20 لتصبح تكلفة10 بسعر بيع12. راجع هل الصنف يتبع النسبة القياسية أم له نسبة مخصصة.','profit')
rule('سعر شراء وحدة الصرف قبل الربح|تكلفة وحدة الصرف|تكلفة الوحدة الحالية','اكتب تكلفة شراء وحدة الصرف قبل الربح من مستند الشراء أو افتتاح المخزون. لو فاتورة المورد بالعلبة حوّلها إلى وحدة الصرف الصحيحة. لا تدخل سعر البيع هنا.','purchases')
rule('سعر الوحدة','راجع عنوان هذا الجزء ووحدة الصرف قبل الإدخال. في التوريد يكون سعر شراء الوحدة قبل الربح، وفي الصرف قد يعرض تكلفة تقديرية؛ لا تستبدله بسعر البيع دون أن يطلب النموذج ذلك.','purchases')
rule('الرصيد الموجود عند بدء الاستخدام','كمية المخزون الفعلية عند بداية استخدام النظام، بوحدة الصرف. سجّلها من مسار الافتتاح أو الجرد المعتمد حتى لا تتكرر مع توريد سابق.','inventory-count')
rule('اسم المورد|المورد المسجل','اختر المورد المسجل أو اكتب اسمه عند إنشاء مورد، مع مطابقة فاتورته وبيانات التواصل. لا تضف اسمًا مكررًا بدل استخدام حسابه الحالي.','purchases')
rule('رقم تشغيلة المصنع LOT / Batch|رقم التشغيلة LOT / Batch إن وجد','انقل رقم الدفعة من عبوة المصنع إذا توفر. إذا لم يتوفر استخدم اختيار غياب كود المصنع أو التتبع الداخلي المتاح، ولا تخترع رقم مصنع.','batch')
rule('تشغيلة موجودة للجرد|التشغيلة|التشغيلة (اختياري)|التشغيلة والصلاحية','اختر الدفعة الفعلية التي تخص العد أو الصرف، وراجع تاريخ انتهائها والكمية المتاحة في المكان. الاختيار التلقائي قد يستخدم الأقرب انتهاء حسب المسار.','batch')
rule('الصلاحية|له صلاحية','حدد هل الصنف يحتاج تتبع صلاحية، أو أدخل تاريخ انتهاء الدفعة إذا كان الحقل تاريخًا. إعداد الصنف لا يغني عن بيانات انتهاء كل دفعة استلام.','batch')
rule('تاريخ الإنتاج إن وجد','اكتب تاريخ الإنتاج المطبوع على الدفعة إن توفر، وليس تاريخ شراء الفاتورة. راجعه مع مدة الصلاحية أو الانتهاء المطبوع.','batch')
rule('مدة الصلاحية بالشهور إن وجدت','عدد الأشهر من تاريخ الإنتاج حتى الانتهاء وفق العبوة، مثل 24. إن لم تتوفر المدة أدخل تاريخ الانتهاء المطبوع في حقله بدل التخمين.','batch')
rule('المخزن المطلوب منه|مخزن الصرف|المخزن المصدر','اختر المكان الذي ستخرج منه الكمية فعليًا وراجع الرصيد والدفعة فيه. مخزن الصرف يختلف عن اسم القسم أو المريض المستفيد.','internal-issue')
rule('المخزن المستقبل|مخزن الاستلام','اختر المخزن الذي سيستلم التوريد أو التحويل، وراجع الفرع والمسؤول. في التحويل يجب أن يختلف عن مخزن المصدر.','transfer')
rule('المكان|المخزن|اسم المخزن','اختر مكان حفظ الكمية المقصودة، أو اكتب اسمًا يميز المخزن عند إنشائه. الأرصدة والجرد والحركات تُراجع على المكان المحدد.','inventory-count')
rule('الغرض من الطلب|الغرض من الاستخدام','اكتب استخدام الكمية ومن المستفيد ولماذا تحتاجها. صرف مستلزم لمريض يربط بالمريض/الزيارة، أما الاستهلاك الإداري فلا يحمله على مريض بلا سبب.','internal-issue')
rule('نوع الإدخال','حدد هل العملية افتتاح مخزون أو جرد فعلي حسب الاختيارات. الافتتاح يثبت بداية الرصيد، والجرد يقارن الموجود بالحركات؛ لا تخلطهما بفاتورة شراء.','inventory-count')
rule('التاريخ والوقت الفعلي للجرد','حدد وقت العد الفعلي للكميات، وليس وقت رفع ملف الجرد إذا اختلف. الوقت يساعد مطابقة الحركات التي تمت قبل العد وبعده.','inventory-count')
rule('المطابقة','اربط سطر الملف المستورد بالصنف الموجود فعلًا أو اختر إنشاء صنف جديد عند عدم وجوده. راجع الاسم والوحدة قبل قبول المطابقة.','inventory-count')
rule('المستلم','اختر الموظف الذي سيستلم الكمية أو العهدة فعليًا في وجهة التحويل حسب الإجراء. لا يعتبر الاختيار وحده إثبات استلام.','transfer')
rule('المستخدم|الموظف المسؤول','اختر حساب الموظف الذي تخصه المسؤولية أو الوردية أو الجرد. راجع تكليفه وصلاحيته بدل اختيار منشئ الطلب تلقائيًا.','inventory-count')
rule('اسم الجرد|اسم خطة الجرد','اكتب اسمًا يميز عملية العد أو خطة تكرار الجرد، مع المكان أو الفترة عند الحاجة لسهولة الرجوع إليها.','inventory-count')
rule('مهلة التسليم بالأيام','عدد الأيام المسموحة لتسليم مهمة الجرد حسب خطة التكليف. هذه مهلة عمل وليست مدة صلاحية صنف.','inventory-count')
rule('آخر موعد للتسليم|موعد التسليم|أول موعد','حدد الموعد الذي يخص المهمة أو خطة الجرد. أول موعد يبدأ منه الجدول، وموعد التسليم آخر وقت مطلوب لإنجاز التكليف.','tasks-guide')
rule('تكرار كل (يوم)','اكتب عدد الأيام بين مرات تكرار الخطة، مثل7 للجرد الأسبوعي. راجع أول موعد والمهلة قبل تشغيل التكرار.','inventory-count')
rule('اسم الفرع|الفرع','حدد الفرع الذي يخص السجل أو المخزن أو الطبيب. راجع أن المكان والتكليف تابعان لنفس الفرع عند تنفيذ حركة.','inventory-count')
rule('نسخ تقسيمات فرع','اختر الفرع الذي تريد أخذ تقسيماته كنموذج عند إعداد فرع، ثم راجع الأسماء والمسؤوليات الجديدة. نسخ التقسيمات لا يعني نقل رصيد المخزون.','inventory-count')
rule('المسؤولية','حدد حدود مسؤولية المستخدم عن المكان أو الجرد وفق التكليف. هذا إعداد صلاحية وعهدة، وليس قرار تحميل مالي لفرق غير مراجع.','inventory-count')
rule('سبب الصرف الإضافي','اكتب سبب إضافة المستلزم للمريض خارج المشمول، وراجع موافقته والزيارة والفاتورة. لا تصرف نفس المستلزم مرة من التنفيذ ومرة من هذا النموذج.','internal-issue')
rule('نوع الهالك','حدد سبب خروج الكمية كهالك مثل تلف أو انتهاء صلاحية حسب القائمة، واربطه بالدفعة والمستند والمراجعة المطلوبة.','inventory-count')
rule('مخزن الهالك|كمية الهالك إن وجدت','اختر المكان والكمية التالفة الفعلية بوحدتها. الهالك يؤثر على المخزون والتكلفة ولا يسجل بيعًا أو تحصيلًا من مريض.','inventory-count')
rule('العدد الفعلي الآن','اكتب الكمية التي عُدت فعلًا في المكان والدفعة المحددين، لا الكمية الدفترية إذا اختلفتا. سيظهر الفرق للمراجعة.','inventory-count')
rule('سبب الجرد وملاحظات العد','اكتب مناسبة الجرد وكيف تم العد وأي ظروف تفسر الفرق، حتى يراجع المسؤول التسوية قبل اعتمادها.','inventory-count')
rule('سبب التحويل','اكتب لماذا تنقل الكمية بين المكانين وما الجهة المستفيدة، حتى يمكن تتبعها مع الإرسال والاستلام.','transfer')
rule('الكمية المستلمة فعليًا في هذه المرة','اكتب ما استلمته فعليًا في هذه الدفعة فقط، خصوصًا عند الاستلام الجزئي. لا تدخل إجمالي الطلب إذا وصل جزء منه.','transfer')
rule('سبب فرق الاستلام إن وجد','اشرح لماذا اختلف المستلم عن المصروف أو المطلوب، مع المستند أو حالة الأصناف إن توفرت، قبل إغلاق التحويل.','transfer')
rule('بحث بالكود أو الصنف أو المورد|بحث بالاسم أو الكود','اكتب جزءًا من الكود أو الاسم المحدد في عنوان البحث لفلترة السجلات. البحث لا يغير بيانات الصنف أو ينشئ كودًا جديدًا.','batch')
rule('بحث باسم المريض أو الهاتف أو رقم الملف|بحث بالاسم أو الهاتف أو رقم الملف','اكتب اسم المريض أو الهاتف أو رقم الملف للعثور على السجل الموجود، ثم طابق الهوية قبل اختياره. النتيجة المتشابهة في الاسم لا تعني نفس المريض.','patient')

rule('الخدمة|اسم الخدمة|الخدمة الأصلية','اختار أو اكتب الخدمة التي يخصها هذا السجل، مع مطابقة كودها وقسمها. في الحجز استخدم الخدمة الجاهزة، وفي الربط اختار تعريفها الأصلي من التسعير.','booking-flow')
rule('كود الخدمة|كود الخدمة في عقد الطبيب|كود النسخة في الاستقبال','استخدم الكود المعتمد للخدمة واربطه بالكود المقابل في العقد والتسعير. اسم الخدمة وحده لا يكفي للمطابقة بين هذه السجلات.','doctor-missing')
rule('سعر الخدمة|سعر الخدمة المتعاقد','اكتب سعر الخدمة الذي يخص التعريف أو العقد في هذه الشاشة، وراجع المشمول والتحمل والخصم. السعر المرجعي أو المتعاقد لا يعني تحصيلًا من المريض.','invoice')
rule('مدة الخدمة بالدقائق|الدقائق','اكتب عدد دقائق الخدمة أو الحجز مثل20. المدة تحدد طول الموعد، ويجب أن تكفيها فترة تواجد الطبيب.','no-slots')
rule('تاريخ الحجز بتوقيت القاهرة|الوقت المتاح بتوقيت القاهرة|بداية التواجد بتوقيت القاهرة|نهاية التواجد بتوقيت القاهرة','اختر تاريخ ووقت القاهرة للحجز أو التواجد حسب الحقل. راجع بداية الفترة ونهايتها ومدة الخدمة؛ ظهور عقد طبيب لا ينشئ مواعيد بلا تواجد.','no-slots')
rule('الطبيب والقسم من عقد الأتعاب المعتمد','اختار الطبيب والقسم من عقد أتعاب ساري ومعتمد ومتوافق مع الخدمة. إذا كانت القائمة خالية راجع نطاق كود الخدمة وشروط الاستحقاق والمراجع المستقل.','doctor-missing')
rule('اسم المريض التجريبي','اسم يستخدم داخل مساحة التدريب فقط. لا تنقل ملفًا حقيقيًا لمساحة التدريب ولا تعتبر هذا الملف بديلًا لملف الأرشيف المتكامل.','booking-flow')
rule('تاريخ الميلاد إن وجد','انقل تاريخ ميلاد المريض الصحيح عند توفره، ولا تستخدم تاريخ الزيارة أو تاريخ اليوم بدلًا منه.','patient')
rule('مساحة العمل','اختار مساحة التشغيل المتاحة لحسابك. التدريب له بيانات منفصلة، والتشغيل المتصل يستخدم سجلات المركز الفعلية ضمن صلاحياته. راجع اسم المساحة قبل الحفظ.','booking-flow')
rule('تصنيف جهة التعاقد','اختار التصنيف الذي ستظهر الجهة داخله. الجهات السابقة موجودة في تعاقدات كاش، والإضافة تبدأ بتصنيف الصفحة المفتوحة. التصنيف منفصل عن نوع الجهة وحالة عقدها.','entities')
rule('اسم الجهة|الجهة','اختار الجهة صاحبة الاتفاق أو اكتب اسمها عند تعريفها، مع مطابقة المستند وبيانات التواصل. لا تخلط موردًا بجهة تأمين أو جهة تعاقد أخرى.','entities')
rule('نوع العلاقة|نوع الجهة','حدد صفة الجهة مثل تأمين أو شركة أو شريك وفق القائمة؛ الصفة تحدد البيانات وطريقة التعامل والمتابعة المناسبة.','entities')
rule('تحمل الجهة %','نسبة قيمة الخدمة التي تتحملها الجهة حسب العقد، وليس ما يدفعه المريض. مثال جهة تتحمل80% يترك20% على المريض قبل أي شروط أو بنود أخرى.','insurance')
rule('الشروط والمستند|شروط التعاقد والمشمولات|شروط المشمول والإلغاء|ملاحظات العقد','اكتب شروط العقد المعتمد بوضوح، بما يشمل الخدمات والمستلزمات والزيارات والصلاحية والإلغاء عند انطباقها. لا تستخدم ملاحظة غير معتمدة لتغيير حق مالي.','package')
rule('مرحلة الاعتماد|حالة التعاقد','اختر أو راجع المرحلة التي وصل إليها العقد بالفعل. المسودة أو المعلق لا يساوي عقدًا معتمدًا ساريًا، والاعتماد يتطلب مراجعًا حسب الصلاحية.','entities')
rule('العقد المعتمد','اختر العقد الذي اكتمل اعتماده وتنطبق فترته وشروطه على هذه العملية. لا تستخدم عقدًا آخر لإكمال حقل فارغ.','entities')
rule('إثبات الأهلية أو رقم الموافقة','اكتب رقم موافقة الجهة أو مستند أهلية المريض لهذه الخدمة وفق العقد. وجود ملف للمريض وحده لا يثبت أن الجهة ستتحمل المبلغ.','insurance')
rule('الفاتورة / الباكج / الإيصال / الطرف','اختر المستند أو الطرف الذي يخص نوع الطلب الحالي. راجع نوعه ورقمه والمبلغ المتبقي قبل إرسال الطلب للمراجعة.','requests')
rule('المبلغ؛ الهالك وطلبات التصحيح صفر','اكتب مبلغ طلب السداد أو الاسترداد حسب العملية. في الهالك أو طلب التصحيح أدخل0 كما يطلب هذا المسار؛ الكمية والتصحيح يُحددان في حقولهما، ولا يعني الصفر عدم وجود أثر محاسبي.','requests')
rule('عند الإشعار الدائن: البند المخفض','حدد أي بند يتم تخفيضه في الإشعار الدائن، مثل الخدمة أو المستلزم بحسب الخيارات، حتى لا ينخفض بند غير المقصود أو يُخفض مرتين.','invoice')
rule('اسم الباكج|الباكج|الباكج إن وجد','اختر تعريف الباكج أو باكج المريض المناسب لهذه العملية، أو اكتب اسمًا يميزه عند إنشائه. راجع الخدمات والزيارات والصلاحية قبل الحجز أو البيع.','package')
rule('إجمالي سعر الباكج','اكتب المقابل المتفق عليه للباكج كاملًا. يختلف عن قيمة دفعة واحدة أو سعر زيارة واحدة، ولا يثبت إيراد كل الخدمات قبل تنفيذها.','package')
rule('نسبة الربح % (على إجمالي الباكج)','نسبة الزيادة التي يطبقها نموذج التسعير على مجموع خدمات الباكج لحساب سعره النهائي. راجع الناتج بدل إضافة نفس الزيادة مرة أخرى عند التحصيل.','package')
rule('الصلاحية بالأيام','عدد الأيام التي يظل فيها حق استخدام الباكج ساريًا وفق شروطه. هذه مدة استخدام الباكج وليست صلاحية دواء أو عدد زيارات.','package')
rule('مرجع النص التعاقدي المؤيد لحق التحصيل','اذكر بند العقد أو المستند الذي يثبت حق التحصيل غير المشروط في هذا المسار. لا تعتبر موعد القسط وحده دليل استحقاق دون شروط العقد.','package')
rule('راجع طبيعة الحق','اختر طبيعة الحق وفق النص التعاقدي الذي يراجعه المسؤول المالي. القرار يحدد معالجة الاستحقاق ولا يستخدم لتجاوز تنفيذ الخدمة أو إثبات تحصيل لم يحدث.','package')
rule('سبب إنهاء الزيارة دون خدمة منفذة إن وجد','اشرح لماذا ستغلق الزيارة بلا تنفيذ، مثل إلغاء المريض أو عدم إتمام الإجراء، وراجع حالة الطلبات والتحصيلات قبل الإغلاق.','booking-flow')
rule('نسبة الخصم %','اكتب نسبة الخصم المعتمدة فقط، مثل10، وراجع أساس تطبيقها وصلاحية منحها. النسبة تختلف عن قيمة المبلغ بعد الخصم.','invoice')
rule('أساس الأتعاب','حدد هل وعاء أتعاب الطبيب يخص الخدمة أو يخصم منه تكلفة المستلزمات وفق الخيارات والاتفاق. طابقه مع العقد قبل التنفيذ.','doctor-missing')
rule('يتطلب جهازًا|الجهاز إن استخدم|الجهاز المحجوز إن لزم','حدد الجهاز المطلوب أو المستخدم فعلًا للخدمة عند انطباق الشرط. راجع توافره وحجزه، ولا تربط جهازًا لم يستخدم فقط لإكمال النموذج.','devices-guide')
rule('كود الجهاز','معرّف ثابت يميز الجهاز داخل النظام. استخدمه لربط الحجز والتشغيل والصيانة بالجهاز الصحيح، وليس برقم فاتورة شرائه.','devices-guide')
rule('نوع العداد','اختار طريقة قياس استخدام الجهاز مثل دقائق أو عداد حسب الإعداد. الاختيار يحدد كيف تفهم قراءات التشغيل وتكاليفه.','devices-guide')
rule('مرجع الأصل إن وجد','اربط الجهاز بالأصل المحاسبي المقصود عند توفره، حتى يمكن مراجعة بياناته وتكلفته دون إنشاء أصل ثانٍ لنفس الجهاز.','devices-guide')
rule('دقائق تشغيل الجهاز إن استخدم','اكتب عدد دقائق التشغيل الفعلية لهذه الخدمة، وليس مدة تواجد الطبيب أو عدد خدمات اليوم.','devices-guide')
rule('قراءة قبل|قراءة بعد','سجل قراءة عداد الجهاز قبل الاستخدام وبعده كما حدثت. راجع أن الفرق يمثل الاستهلاك المقصود وبوحدة العداد المحددة.','devices-guide')
rule('سبب اختلاف الاستهلاك عن المكونات إن وجد','اشرح لماذا اختلفت الكمية الفعلية من المستلزمات عن الوصفة الافتراضية للخدمة، مع مراجعة المشمول والإضافات قبل التنفيذ.','internal-issue')
rule('الموافقة على الإضافات','سجل موافقة المريض الفعلية على الإضافات المدفوعة بعد توضيح سعرها. هذا الاختيار لا يعني موافقة تلقائية لكل مريض أو صرفًا سبق تنفيذه.','internal-issue')
rule('الليد المرتبط بنفس ملف المريض|الليد المرتبط بنفس ملف المريض إن وجد','اختار الليد المرتبط بملف هذا المريض لربط التواصل بالحجز ومصدره. لا تربط ليدًا لشخص آخر بسبب تشابه الاسم أو الهاتف المشترك.','leads-guide')
rule('الموافقة|مرجع الموافقة أو طلب إيقاف التواصل','سجل موافقة المريض على التواصل أو طلبه إيقافه ومرجع ذلك حسب النموذج. الموافقة على الحجز لا تفترض موافقة على كل رسالة تسويقية.','communications-guide')
rule('نوع التواصل|نص المسودة','حدد غرض الرسالة واكتب نصها للمراجعة وفق حالة الحجز والموافقة. حفظ المسودة أو فتح واتساب لا يثبت إرسالًا أو تسليمًا.','communications-guide')
rule('دليل الإسناد','اختر الدليل الذي يثبت مصدر الحجز بحسب المسار، وأرفق مرجعه. إفادة المريض تختلف عن تتبع إعلان مؤكد، ولا يثبت التتبع بمجرد اختيار القناة.','booking-source')
rule('معرف الإعلان من تقرير Meta','انقل معرّف الإعلان من تقرير ميتا الذي يخص العملية، وليس اسم الحملة أو رقم الحجز. راجع دليل الإسناد قبل اعتماد الربط.','ads-guide')
rule('مرجع تقرير الإنفاق أو المستند|نتيجة المطابقة ومرجع القرار|نتيجة مراجعة الأرقام والتغطية','اذكر مصدر الأرقام ونتيجة مطابقتها بالفترة والحملة أو السجلات، مع تفسير أي فرق قبل اعتماد التقرير.','indicators')
rule('نوع الأصل|السجل في الاستقبال|الأصل في النظام','في شاشة الربط حدد نوع السجل ومرجعه في الاستقبال ومرجعه الأصلي بالنظام. طابق الطرفين من سجلاتهما، ولا تخترع معرّفًا أو تعيد إنشاء السجل لإتمام الربط.','integration-guide')
rule('الكود المحاسبي للطبيب إن كان الربط لطبيب','كود الطبيب الثابت المعتمد في الحسابات لربط سجله، وليس كود الخدمة أو اسم الطبيب. طابقه بعقد الطبيب قبل الحفظ.','doctor-missing')
rule('نتائج التجربة والنواقص بالتفصيل','سجل ما اختبرته والنتيجة والفروق المتبقية بالمستندات. لا تعتمد التجربة نيابة عن موظف لم يختبرها أو تصف بيانات محاكاة بأنها تشغيل فريق فعلي.','integration-guide')
rule('كلمة السر|كلمة السر الجديدة','اكتب كلمة المرور الخاصة بك وفق شروط النموذج. عند التغيير استخدم كلمة جديدة، والمساعدة تشرح الحقل دون قراءة القيمة التي كتبتها.','access')
rule('تأكيد كلمة السر','أعد كتابة نفس كلمة المرور الجديدة للتأكد من تطابق الإدخال. هذا ليس مكان كلمة المرور السابقة.','access')
rule('بحث في الأقسام المتاحة لك|بحث|بحث عن مادة','اكتب اسم القسم أو جزءًا من اسم السجل المطلوب. النتائج تعتمد على صلاحية حسابك والبيانات المتاحة، والبحث لا يغير السجلات.','personal')
rule('رسالة الشكر','اكتب سبب شكرك للزميل أو العمل الذي تقدره، واختر المستلم الصحيح قبل الإرسال.','personal')
rule('مواد المحتوى (ساعة)','عدد الساعات المستخدم كحد متابعة لتأخر مواد المحتوى بحسب إعداد التنبيه. لا يمثل موعد نشر تلقائي أو ساعات عمل الموظف.','access')
rule('ليدز جديدة من غير رد (ساعة)','عدد الساعات الذي يحدد متى يُعد الليد الجديد متأخرًا بلا رد في تنبيهات المتابعة. عدل الحد حسب سياسة الفريق.','access')
rule('من|من تاريخ|من تاريخ البدء|إلى|إلى تاريخ|لـ|يبدأ|ينتهي|اليوم|التاريخ','حدد بداية أو نهاية الفترة أو اليوم وفق عنوان الحقل ونوع الإدخال. في الفلاتر يغير العرض فقط، وفي العقد أو التواجد يحدد السريان. راجع ترتيب البداية والنهاية والمنطقة الزمنية المكتوبة.','personal')
rule('المتابعة القادمة|موعد المتابعة القادمة','حدد تاريخ المتابعة المقبلة بعد تسجيل نتيجة المحاولة الحالية، ثم راجع المسؤول عن متابعتها. لا تستخدمه بدل موعد حجز المريض.','leads-guide')
rule('ملاحظة|ملاحظة (اختياري)|ملاحظات|التفاصيل','اكتب تفاصيل هذا السجل التي يحتاجها المراجع أو المنفذ ولا تغطيها الحقول الأخرى. تجنب نسخ بيانات حساسة لا تخص الغرض، ولا تستخدم الملاحظة بدل المستند أو القرار.','personal')
rule('وصف الخدمة|وصف الخدمة أو الصرف','صف الخدمة المقدمة أو غرض الصرف كما هو في المستند، حتى يستطيع المراجع تمييزها عن الحركات الأخرى. لا تضع مبلغًا أو اسم مريض بدل الوصف.','invoice')
rule('المطلوب|عنوان المهمة|وصف المطلوب|المطلوب من الموظف|التوجيه والخطوات المطلوبة','اكتب العمل الذي يجب تنفيذه ومن أين يبدأ وما الذي يجب تسليمه. استخدم طلبًا يمكن للمسؤول فهمه ومراجعته بدل عنوان عام.','tasks-guide')
rule('المشروع|اسم المشروع|مشروع الفريق|المهمة','اختر المشروع أو المهمة التي تخص هذا التكليف، أو اكتب اسمًا يميز المشروع عند إنشائه. اربط المهمة بوالدها الصحيح حتى تظهر داخل تسلسلها.','tasks-guide')
rule('وصف الخطة','اشرح نتيجة المشروع وخطواته ونطاقه وما يعتمد عليه من أقسام أخرى، ثم وزع المهام بدل وضع كل التفاصيل في عنوان المشروع.','tasks-guide')
rule('مدير المشروع','اختر الحساب المسؤول عن متابعة المشروع وتوزيع مهامه ومراجعة تقدمه حسب صلاحياته. هذا لا يمنحه صلاحيات مالية أو إدارية إضافية.','tasks-guide')
rule('شكل التسليم|النتيجة المتوقعة|النتيجة المتوقعة ومعيار القبول','حدد ما الذي سيُراجع عند اكتمال المهمة، مثل ملف جرد أو رابط تقرير أو عدد مستندات مطابق. وضّح معيار القبول قبل بدء التنفيذ.','tasks-guide')
rule('الأولوية','حدد ترتيب أهمية العمل من القائمة. الأولوية تساعد تنظيم البداية، لكنها لا تستبدل موعد التسليم أو الاعتماد المطلوب.','tasks-guide')
rule('الفترة|إيقاف التكرار في (اختياري)','حدد وحدة تكرار المهمة أو تاريخ إيقاف التكرار حسب الحقل. راجع العدد وموعد أول تنفيذ حتى لا ينشئ الجدول تكليفات في فترة غير مطلوبة.','tasks-guide')
rule('اكتب شغلك هنا أو أرفق ملفًا|رابط الشغل (اختياري)|إضافة ملفات|📎 إرفاق ملفات','أدخل نتيجة العمل أو رابطًا يمكن للمراجع فتحه وأرفق الملفات التي تثبت التنفيذ. راجع صلاحيات الرابط والمرفق قبل إرسال المهمة للمراجعة.','tasks-guide')
rule('الحالة|حالة السوشيال','اختار الحالة الفعلية أو فلتر العرض حسب هذه الشاشة. تغيير الفلتر لا ينقل المستند لمرحلة جديدة، والحالة التنفيذية لها إجراء وصلاحية مستقلان.','personal')
rule('تقرير المتابعة','اختر التقرير الذي ستسجل نتيجة متابعة إجراءاته، وطابق الفترة والمؤشر قبل تقييم التنفيذ.','indicators')
rule('النتيجة|النتيجة الموثقة','سجل ما تحقق بعد التنفيذ مع ما يثبته. ميّز النتيجة الفعلية عن النتيجة المتوقعة أو اقتراح لم يبدأ.','indicators')
rule('القيمة المقاسة','اكتب القياس الفعلي للمؤشر في الفترة المحددة وبوحدته، مثل عدد الحجوزات أو نسبة التحويل. راجع مصدر القياس قبل الحكم على الأثر.','indicators')
rule('دليل الحكم وتفسيره','اذكر المستند أو القياس الذي بنيت عليه تقييم النتيجة، واشرح علاقته بمعيار القبول والفترة بدل تسجيل حكم بلا دليل.','indicators')
rule('المرحلة','اختر المرحلة التي وصل إليها العمل فعلًا، مع استكمال المطلوب منها. تخطي مرحلة لا يعوض اعتمادًا أو إجراءً لم يحدث.','tasks-guide')
rule('المخرج الذي يثبت التنفيذ','حدد ملفًا أو رابطًا أو مستندًا يثبت إنجاز المرحلة، مع إمكانية وصول المراجع إليه. كتابة «تم» وحدها لا توضح ما نُفذ.','tasks-guide')
rule('موعد المرحلة بتوقيت جهازك|موعد تسليم المهمة بتوقيت جهازك','اكتب تاريخ ووقت التسليم وفق توقيت الجهاز كما ينص الحقل. راجع المنطقة الزمنية إذا كنت خارج مصر، ولا تفترض أنه حقل بتوقيت القاهرة.','tasks-guide')
rule('موعد التسليم بتوقيت القاهرة','حدد موعد التكليف بتوقيت القاهرة، وميّزه عن حقول أخرى مكتوب عليها توقيت الجهاز. راجع التاريخ والساعة قبل الحفظ.','tasks-guide')
rule('أقرب تاريخ لقياس الأثر','اختر أول تاريخ يمكن فيه قياس نتيجة الإجراء بعد تنفيذه. لا تقارن أثر حملة أو تغيير قبل أن تتوفر له مدة وبيانات مناسبة.','indicators')
rule('لينك اللوكيشن (جوجل ماب)','ضع رابط موقع الفرع الصحيح على خرائط جوجل بعد فتحه والتحقق من العنوان، حتى لا يُوجّه المريض لفرع آخر.','chatbot')
rule('الموقع','رابط الموقع الإلكتروني الرسمي للمركز في هذا الحقل، وليس العنوان البريدي أو رابط خرائط المكان.','chatbot')
rule('طرق الدفع المتاحة','حدد طرق السداد التي يقبلها المركز فعليًا في المعلومات العامة. هذا الوصف لا يفتح خزينة أو يثبت تحصيلًا ماليًا.','chatbot')
rule('اسم العرض|السعر / الخصم','اكتب اسم العرض أو سعره/خصمه المعتمد وفق الحقل، وراجع الفترة والشروط والخدمات المشمولة قبل إتاحته للمستخدمين.','chatbot')
rule('السؤال|الإجابة المعتمدة','اكتب السؤال الشائع أو الرد الذي راجعته الإدارة في الحقل المقابل. الرد يجب أن يتفق مع المواعيد والأسعار والشروط الحالية دون إدخال بيانات مرضى.','chatbot')
rule('الخدمات المتفق عليها','اكتب أو اختر الخدمات التي ينص عليها عقد الجهة، مع الأسعار أو الشروط في حقولها. لا تعتبر باقي خدمات المركز مشمولة تلقائيًا.','entities')
rule('اسم مسؤول التعاقد','اكتب أو اختر المسؤول الذي يتابع الاتفاق والتواصل مع الجهة وفق التكليف، حتى يعرف الفريق لمن يرجع عند نقص مستند أو سؤال.','entities')
rule('تسجيل متابعة|تسجيل محاولة تواصل','سجل وقت المحاولة وما حدث ونتيجتها الفعلية ثم حدد الموعد التالي. لا تعتبر عدم الرد موافقة أو حجزًا مؤكدًا.','leads-guide')
rule('نوع المعاملة','اختر تصنيف المعاملة المقصودة حسب قائمة الجهة أو الحساب، مع ربطها بالمستند؛ التحصيل يختلف عن استحقاق قيمة الخدمة.','entities')
rule('ملف العقد|الملف (صورة / PDF / إكسيل)','ارفع المستند المطلوب بالسجل الصحيح وراجع امتداده ومحتواه وصلاحية وصول المراجعين إليه. الرفع وحده لا يعتمد عقدًا أو يرحل معاملة.','entities')
rule('اسم العميل','اكتب اسم صاحب الاستفسار كما ورد بعد البحث بالهاتف لتجنب التكرار. الاسم وحده لا يثبت أنه نفس ملف مريض موجود.','leads-guide')
rule('نص الرسالة (اختياري)','انقل مضمون الاستفسار أو الرسالة التي تخص الليد دون تغيير معناه أو إضافة بيانات حساسة لا يحتاجها التواصل.','leads-guide')
rule('الخدمة المهتم بيها (اختياري)|مصدر الاهتمام (اختياري)','سجل الخدمة أو المنشور أو سبب الاهتمام الذي ورد في الاستفسار، وميّز ما قاله العميل عن استنتاج الموظف أو تتبع مؤكد للحملة.','leads-guide')
rule('رقم/مرجع الحجز','انقل مرجع الموعد الذي تم حجزه لهذا الليد إذا كان موجودًا فعلًا، حتى يربط التواصل بالموعد. لا تضع رقمًا افتراضيًا لتغيير الحالة إلى محجوز.','leads-guide')
rule('الميزانية اليومية|الميزانية الإجمالية','اكتب حد الإنفاق الإعلاني اليومي أو الإجمالي حسب الحقل والعملة. راجع مدة الحملة والموافقة، فهذا ليس إيراد المركز أو تكلفة إنتاج التصميم.','ads-guide')
rule('ملخص الاستهداف','اكتب الجمهور والموقع والقيود التي تستهدفها الحملة وفق الخطة المعتمدة، دون إضافة قوائم مرضى أو استهداف حساس غير مصرح به.','ads-guide')
rule('ملخص الاستراتيجية','اشرح هدف الحملة والجمهور والميزانية والإبداع ومعيار القياس الذي ستراجعه، مع تمييز المقترح عن إجراء جرى تنفيذه.','ads-guide')
rule('الحملة','اختر الحملة الإعلانية المعنية من الحساب الصحيح والفترة المقصودة. لا تخلط اسم الحملة بمعرف الإعلان أو بموضوع منشور غير ممول.','ads-guide')
rule('هتتنشر على (تقدر تختار أكتر من منصة)','حدد المنصات التي ستنشر عليها المادة المعتمدة، وراجع الصفحة والهوية ومتطلبات كل منصة. اختيار المنصة لا يعني أن النشر تم.','publishing-guide')
rule('فترة السماح قبل الجدولة (دقيقة)','عدد الدقائق التي تظل فيها المادة الجاهزة متاحة للجدولة اليدوية قبل أن تجدولها المهمة التلقائية. الحد الأدنى 5 دقائق، ويطبق فقط عند تفعيل الجدولة التلقائية.','publishing-guide')
rule('معاد النشر المجدول|تعديل ميعاد النشر','اختر موعد نشر المادة وفق المنطقة الزمنية الموضحة في شاشة الجدولة، وراجع محتواها والمنصات. الجدولة تظل مختلفة عن تأكيد النشر الفعلي.','publishing-guide')
rule('رابط المنشور للمنصات اليدوية فقط (تيكتوك/يوتيوب)|رابط المنشور للمنصات اليدوية فقط','ضع الرابط الفعلي للمادة بعد نشرها يدويًا على المنصة المطلوبة. رابط المعاينة أو ملف التصميم ليس رابط منشور منشور للجمهور.','publishing-guide')
rule('اختر جهة تنفيذ التصميم|جهة تنفيذ التصميم','اختر الموظف أو مسار التنفيذ المخول بإنتاج التصميم حسب الخيارات، ثم راجع الاستلام والرفع والاعتماد. التكليف لا يساوي اعتماد التصميم.','design-guide')
rule('المستهدف','اكتب قيمة الهدف للفترة والمؤشر المعنيين وبنفس وحدته، لا النتيجة الحالية. الهدف يستخدم للمقارنة بعد تسجيل الأداء الفعلي.','indicators')
rule('فلترة بالشهر|بداية الأسبوع','اختر الشهر أو تاريخ بداية الأسبوع الذي تريد عرض أو إدخال بياناته. راجع الفترة قبل مقارنة الأرقام أو استيراد تقرير.','indicators')
rule('أو ارفع تقرير CSV (Meta Business Suite / Meta Ads / Google Ads)','ارفع ملفCSV المصدر للفترة المطلوبة، وراجع مطابقة الأعمدة والأرقام والمعاينة قبل اعتماد الاستيراد. تحقق هل المسار يستبدل بيانات سابقة قبل الحفظ.','indicators')
rule('الوصول (Reach)','عدد الحسابات التي وصل إليها المحتوى حسب التقرير الأصلي والفترة. لا تدخل عدد المشاهدات أو مرات الظهور بدل الوصول إذا اختلف تعريفهما.','indicators')
rule('نسبة التفاعل %','اكتب النسبة المئوية كما يحسبها التقرير المعتمد مع مراجعة أساسها. نسبة5% تدخل5، وليس عدد التفاعلات أو0.05 إذا كان الحقل يطلب بالمئة.','indicators')
rule('متابعين جدد','عدد المتابعين الذين أضيفوا خلال الفترة حسب المصدر، وليس إجمالي متابعي الصفحة. راجع هل التقرير يعرض إضافة فقط أم صافي التغير.','indicators')

rule('البحث في الداشبورد|بحث في القائمة','اكتب اسم القسم أو الإجراء المطلوب لعرض الروابط المتاحة لحسابك. الفلترة لا تمنح صلاحية لقسم محجوب.','personal')
rule('سبب القيد والمستند|سبب القرار والمستند','اكتب سبب إنشاء أو مراجعة القيد والمستند الذي يؤيده، مع توضيح ما تصححه إذا كان بديلًا لقيد سابق. راجع الفترة والتوازن والمراجع المستقل.','ledger-guide')
rule('سعر شراء الوحدة','اكتب تكلفة شراء الوحدة المحددة في هذا السطر قبل نسبة ربح المركز، مع مطابقتها بفاتورة المورد ووحدة الصرف.','purchases')
rule('البند','اختر سطر المستند الأصلي الذي ستستلم أو تعالج كميته، مع مراجعة الصنف والمطلوب والمتبقي من نفس الطلب.','purchases')
rule('الكمية المستلمة','اكتب العدد الذي وصل فعلًا في هذه الدفعة، بوحدة السطر. لا تؤكد استلام إجمالي الطلب إن وصل جزء منه.','purchases')
rule('العدد في الزيارة|رقم زيارة الباكج','عدد الخدمة في زيارة الباكج أو ترتيب الزيارة حسب عنوان الحقل. راجع خطة الباكج وخدمات كل زيارة قبل الحفظ حتى لا تخصم زيارة أو خدمة مرتين.','package')
rule('تاريخ القسط','موعد الدفعة المجدولة حسب اتفاق الباكج. موعد القسط تذكير بالتحصيل ولا يثبت قبض المال أو استحقاق إيراد كل الخدمات.','package')
rule('كمية لكل وحدة خدمة','كمية المستلزم التي تدخل افتراضيًا في تنفيذ وحدة واحدة من الخدمة، بوحدة المستلزم المرتبط. راجع معامل التحويل إلى وحدة المخزن.','supply-map')
rule('المستلزم — سعر بيع الوحدة','اختار المستلزم الإضافي وفق سعر البيع المعروض للمريض، وراجع هل هو مشمول أصلًا في الخدمة قبل إضافة مبلغ عليه.','internal-issue')
rule('الكمية الفعلية','سجل الكمية التي استُخدمت فعلًا في التنفيذ بوحدتها، وفسر أي فرق عن المكونات الافتراضية قبل تأكيد الصرف.','internal-issue')
rule('الدور','اختر دور الموظف الذي ستعرض أو تعدل مستهدفاته وأوزان مؤشراته، وليس حساب شخص منفرد أو منح صلاحية جديدة.','indicators')
rule('إيه اللي اتعمل أو هتشتغل عليه؟|ملخص الإنجاز','اكتب ما أنجزته فعلًا وما ستبدأه أو ما تسلمه للمراجع، مع ملف أو رابط يثبت النتيجة عند الحاجة. لا تسجل المهمة منتهية قبل تحقق معيار التسليم.','tasks-guide')
rule('إيه اللي موقفك؟','اشرح العائق المحدد وما الإجراء أو الشخص الذي تنتظره، مثل انتظار سعر من المورد، حتى يقدر المسؤول يوجه المساعدة.','tasks-guide')
rule('ملاحظة الاعتماد (اختياري)|المطلوب تعديله','سجل نتيجة مراجعة العمل أو التعديل المطلوب بعبارة محددة، وما الذي سيقبله المراجع عند إعادة التسليم.','tasks-guide')
rule('الترتيب','اكتب ترتيب تنفيذ المهمة ضمن مهام الموظف كما يسمح النموذج. الترتيب يوضح البداية والتتابع ويختلف عن درجة الأولوية وموعد التسليم.','tasks-guide')

rule('اكتب حرفين على الأقل…|ابحث عن قسم…|اكتب 3 حروف على الأقل|بحث بالاسم / الهاتف / المرجع / الطبيب…|بحث بالاسم / الهاتف|بحث عن مريض…|بحث بالاسم / الهاتف / كود المريض|كود التتبع أو اسم الصنف|ابحث باسم المهمة أو المسؤول أو المشروع…|دوّر بالاسم / اسم الحملة / رقم الإعلان / مجموعة الكرييتف / التخصص','اكتب جزءًا من البيان المطلوب في عنوان البحث، مع الالتزام بالحد الأدنى للحروف إن وُجد، ثم اختر النتيجة الصحيحة. البحث لا ينشئ سجلًا ولا يغيره.','personal')
rule('مثال: شكراً على المجهود الرائع في حملة الأسبوع ده!','اكتب سبب الشكر والعمل الذي تقدره للموظف المحدد، ثم راجع المستلم قبل الإرسال.','personal')
rule('اكتب كومنت...|اكتب الرد…|اكتب تعليق، أو الصق رابط ملف (Drive مثلاً)…|السبب في جملة (اختياري)','اكتب تعليقًا يخص المادة أو نتيجة المراجعة، مع تحديد المطلوب أو سبب تقييمك. لو أضفت رابط ملف تأكد من إتاحته للمراجع، ثم سجل حالة التعديل حسب الإجراء.','content')
rule('اسم الجهاز الجديد','اكتب اسم الجهاز أو أسلوب العلاج الذي تريد إضافته لقائمة الاختيار، وراجعه قبل الحفظ حتى لا يكرر عنصرًا موجودًا. الإضافة للقائمة لا تنشئ أصلًا محاسبيًا.','devices-guide')
rule('رصيد مقدم قديم موثق، دون تحصيل جديد، قبل اعتماد الافتتاح.','حدد هذا الإقرار فقط عند إدخال رصيد مقدم قديم موثق قبل اعتماد الافتتاح. لا تستخدمه كتحصيل جديد أو لإضافة كاش لم يدخل الخزينة.','collections')
rule('راجعت القناة وتأكدت من النتيجة قبل القرار.','أكد الإقرار بعد فحص وسيلة الدفع ودليل وصول المبلغ أو عدم وصوله. لا تعتمده بناءً على طلب دفع أو رسالة فقط.','collections')
rule('أؤكد أن الرسالة أُرسلت بالفعل للحجز الحالي.','ضع علامة فقط إذا تحققت من إرسال الرسالة بالفعل لهذا الحجز. تجهيز النص أو فتح القناة ليس إثبات إرسال.','communications-guide')
rule('أؤكد تنفيذ الخدمة وعدم تسجيلها سابقًا في الدورة المالية.|أؤكد تنفيذ الخدمة أو تسليم المستلزمات وعدم تسجيل الفاتورة سابقًا.','أكد التنفيذ أو التسليم الفعلي بعد مراجعة السجل للتأكد من عدم تسجيل نفس الحدث سابقًا. الإقرار يترتب عليه أثر مالي ولا يصلح لإثبات حجز لم ينفذ.','invoice')
rule('راجعت الحركات والورديات حتى هذا التاريخ.','حدد الإقرار بعد مطابقة حركات الفترة ووردياتها وتسوياتها قبل الإقفال. لا تستخدمه لمجرد إخفاء فرق غير محلول.','cash-shifts-guide')
rule('أعتمد معالجة المردودات والتخفيضات بتخفيض الوعاء بنسبة انخفاض الإيراد مع إبقاء تكلفة المستلزمات المصروفة.','راجع بند العقد قبل الإقرار بهذه السياسة: تخفض المردودات وعاء أتعاب الطبيب وفق انخفاض الإيراد، وتبقى تكلفة المستلزمات التي صُرفت. الموافقة تحتاج توافق الاتفاق ومراجعه.','doctor-missing')
rule('الصنف غير مفتوح وصالح للإعادة بعد الفحص.','حدد الإقرار بعد فحص الصنف المرتجع والتأكد من أنه غير مفتوح وصالح للإعادة وفق المسار، لا لمجرد أن المريض طلب الاسترداد.','purchases')
rule('راجعت الصرف السابق، وهذه كمية إضافية جديدة فعلًا وليست إعادة تسجيله','راجع سجل الصرف والفاتورة ثم أكد أن الكمية إضافية جديدة بالفعل. لا تكرر صرف مكون سُجل من تنفيذ الخدمة.','internal-issue')
rule('المريض وافق على قيمة المستلزم الإضافي الظاهرة','حدد الإقرار بعد توضيح سعر البيع الإضافي للمريض والحصول على موافقته، وقبل تسجيل الصرف والفاتورة المرتبطين.','internal-issue')
rule('إرسال للمراجعة بعد استكمال كل الأصناف','اختار الإرسال بعد مراجعة كميات جميع الأصناف ووحداتها. السطور غير المعدودة لا تعتبر رصيدها صفرًا، والمراجعة لا تتم بمجرد رفع الملف.','inventory-count')
rule('تطبيق النسبة على جميع الأصناف الحالية أيضًا بدل نسبها الخاصة','حدد هذا الخيار فقط إذا أردت استبدال نسب الأصناف الحالية بالنسبة القياسية أيضًا. تركه غير محدد يحافظ على سياسة الأصناف الخاصة حسب إعداد النموذج.','profit')
rule('أعتمد التكليف والمسؤول والمراحل ومواعيدها','راجع العمل والمسؤول والمراحل ومواعيد التسليم قبل تأكيد التكليف، ثم تابع الإنجاز والمخرج الذي يثبت كل مرحلة.','tasks-guide')
rule('تطبيق التعديلات على التكرارات القادمة','حدد الخيار إذا أردت أن تتبع النسخ القادمة من المهمة المتكررة هذه التعديلات أيضًا. راجع أثره على التكليفات القادمة قبل الحفظ.','tasks-guide')
rule('2026-10-17, BANK-001, 250.00','مثال لصيغة سطر كشف البنك: تاريخ ثم مرجع ثم مبلغ تفصل بينها فواصل. ضع كل حركة في سطر مستقل، والداخل موجب والخارج سالب.','bank')
rule('1112, 1000, 0, 3210, 0, 1000,','مثال لطرفي قيد: كود حساب ثم مدين ثم دائن لكل سطر حسب تنسيق النموذج. استبدل المثال بحساباتك ومبالغ مستندك، وراجع التوازن قبل الإرسال.','ledger-guide')
rule('نتيجة الاتصال أو الاجتماع','اكتب ما تم الاتفاق عليه أو ما تعطل وموعد الخطوة التالية بعد الاتصال أو الاجتماع، مع مرجع مستند عند وجوده.','entities')
rule('ملاحظة مختصرة (نقطة قوة / نقطة تطوير)','اكتب ملاحظة أداء مرتبطة بعمل أو مؤشر ودليل خلال الفترة، مع خطوة يمكن للموظف تنفيذها للتحسين.','indicators')
rule('رابط الشغل (اختياري)|https://…|https://...','ضع الرابط الفعلي المطلوب في عنوان النموذج، مثل رابط منشور منشور أو ملف تسليم. تأكد أنه يفتح للمراجع ولا تستخدم رابط معاينة بدل المستند المطلوب.','personal')
rule('عنوان المادة','اكتب عنوان المادة أو جزءًا منه للعثور عليها في قائمة النشر حسب المرشح الحالي. البحث لا يضيف مادة جديدة.','publishing-guide')
rule('مثال: حددي فئات الجمهور واحتياجات كل فئة للخدمات المسندة إليك','اكتب المطلوب من الموظف في صورة خطوات ونتيجة محددة، مع الخدمات أو نطاق العمل الذي سيعمل عليه.','tasks-guide')
rule('مثال: جدول Word أو Excel، لكل فئة الخدمة والاحتياج ومخاوف الجمهور','حدد تنسيق التسليم ومحتواه مثل جدول بالأعمدة المطلوبة، حتى يعرف الموظف ما الذي سيراجعه المسؤول.','tasks-guide')
rule('أضف بند جديد واضغط إضافة','اكتب بندًا واحدًا واضحًا في قائمة المهمة ثم اضغط إضافة. راجع القائمة قبل إرسال العمل حتى لا تتكرر البنود.','tasks-guide')
rule('الصق النص أو اكتب اللي خلصته…','اكتب العمل الذي أنجزته وأرفق المستندات أو الروابط التي تثبته، ثم اختر الإجراء المناسب مثل حفظ تقدم أو إرسال للمراجعة.','tasks-guide')
rule('لم يُعدّ','هذه علامة لسطر لم يتم عدّه بعد. أدخل العدد الفعلي عند اكتمال العد، ولا تحوله إلى صفر من غير جرد حقيقي.','inventory-count')
rule('اسم العملية','اسم العملية الجراحية السابقة كما ورد في ملف المريض أو إفادته مع التاريخ المتاح. لا تضع إجراءً مقترحًا ضمن العمليات التي تمت بالفعل.','patient-records')
rule('المرض|ضغط/سكر/غدة درقية/كلى/أورام/تنفسية/أخرى...','سجل المرض المذكور في التاريخ المرضي وفق الإفادة أو المستند، مع توضيح مصدر المعلومة. لا تضف تشخيصًا غير موثق.','patient-records')
rule('اكتب السبب الآخر|اذكرها','اكتب التفصيل الذي يقصده خيار «أخرى» في هذا الجزء من النموذج، مع الرجوع لسؤال الحقل بدل إدخال وصف لا يخصه.','patient-records')
rule('اسم الطبيب المحوّل له','اكتب اسم الطبيب أو التخصص الذي تم تحويل المريض إليه وفق قرار الطبيب، مع توثيق سبب التحويل في حقله.','patient-records')
rule('اسم الدواء','انقل اسم الدواء من وصفة الطبيب كما هو، مع التركيز والجرعة في حقليهما. لا تضع اسم المادة أو دواء بديلًا بالتخمين.','patient-records')
rule('التركيز','انقل تركيز الدواء ووحدته من العبوة أو الوصفة، مثل القيمة المكتوبة بالملليجرام. يختلف التركيز عن كمية الجرعة التي يتناولها المريض.','patient-records')
rule('الجرعة','اكتب كمية الجرعة التي وصفها الطبيب بوحدتها، مع التكرار والمدة في الحقول المقابلة. لا تستنتج جرعة من العمر أو الوزن داخل هذا النموذج.','patient-records')
rule('وحدة ساعة يوم','اختر وحدة فاصل الجرعات حسب الوصفة مثل ساعة أو يوم، مع العدد المكتوب في «كل». راجع الفرق بين كل8 ساعات وكل8 أيام.','patient-records')
rule('تعليمات إضافية للمريض','انقل تعليمات الطبيب الخاصة بالاستخدام أو المتابعة، مع تمييزها عن ملاحظة داخلية للفريق.','patient-records')
rule('تحاليل تانية غير موجودة في القائمة|أشعة تانية غير موجودة في القائمة','اكتب الفحوص التي طلبها الطبيب ولم تجدها ضمن الخيارات، مع اسمها وموضعها والجهة إن لزم، دون تكرار ما اختير بالفعل.','patient-records')
rule('أي ملاحظات من العميل','دوّن ملاحظات المريض كما وردت وميّزها عن رأي الطبيب أو نتيجة الفحص.','patient-records')
rule('سطر عادي = عنوان بولد (➢)، وسطر يبدأ بـ - = تفصيل تحته (•)','اكتب نص التقرير بحسب تنسيق هذا المحرر: السطر العادي عنوان، والسطر الذي يبدأ بشرطة تفصيل تحته. راجع معاينة الطباعة للتأكد من الترتيب.','patient-records')
rule('رقم السن','اكتب رقم السن وفق ترقيم نموذج الأسنان الذي يستخدمه الطبيب، مع مراجعة الجهة والمخطط. لا تستخدم ترتيب الجلسة بدل رقم السن.','patient-records')
rule('الخدمة اللي اتعملت','سجل الإجراء الذي نُفذ بالفعل في الجلسة وفق ملاحظة الطبيب. كتابة الإجراء في التقرير لا تعوض تسجيل تنفيذه في المسار المالي عند الحاجة.','patient-records')
rule('المدة (Time)|المدة','اكتب مدة الجلسة أو الاستخدام المقصود بوحدة الحقل، مع التمييز بينها وبين فترة العلاج الكاملة أو فاصل تكرار الجرعة.','patient-records')
rule('تشخيص الحالة العام — منفصل عن تحديد نقط الـ area على الرسم','اكتب التشخيص العام الذي وثقه المختص. أما مواضع الألم فتحدد على الرسم، ولا تستبدل أحد الجزأين بالآخر.','patient-records')
rule('اسم الوجبة (مثال: الإفطار)','اسم الوجبة في خطة التغذية مثل الإفطار، مع مكوناتها وكمياتها في الحقول المقابلة.','patient-records')
rule('المكونات (افصل بفاصلة)','اكتب مكونات الوجبة حسب خطة الأخصائي وافصل بينها بفواصل كما يطلب المحرر، مع عدم تغيير كمياتها دون مراجعة المختص.','patient-records')
rule('السعرات','سجل عدد السعرات الذي حدده أخصائي التغذية لهذه الوجبة أو الخطة وفق عنوان الحقل. لا تستخدم وزن الطعام أو سعره مكان القيمة.','patient-records')
rule('سبب الرفض (اختياري)','اشرح ما الذي منع اعتماد السجل أو الطلب بعد المراجعة، مع الخطوة المطلوبة لتصحيحه. لا ترفض سجلًا من غير مراجعة المستند وصلاحية القرار.','patient-records')
rule('الأهداف المطلوب العمل عليها','اكتب أهداف التقييم أو الخطة التي حددها المختص، بما يسمح بتوثيق العمل والاستجابة خلال الجلسات.','patient-records')
rule('التمارين والمهارات التي تم التدريب عليها','سجل التدريب الذي تم بالفعل في الجلسة وفق توثيق المختص، وليس جميع تدريبات الخطة المستقبلية.','patient-records')
rule('ما يطبقه الطفل في المنزل','انقل الواجب المنزلي الذي اعتمده المختص مع طريقة التطبيق والتكرار والمدة إن حددها، دون إضافة تمارين من عندك.','patient-records')
rule('حضر|غاب|اعتذر','حدد حالة حضور الجلسة الفعلية حسب الخيار. الاعتذار يختلف عن الغياب، ولا يعتبر الموعد المحجوز جلسة منفذة.','patient-records')
rule('ملاحظات الجلسة','سجل ما لاحظه المختص أو ما حدث في هذه الجلسة، مع ربطه بتاريخها وأهدافها والاستجابة، وميّزه عن الخطة القادمة.','patient-records')
rule('نعم|لا','اختر الإجابة التي تنطبق على السؤال الطبي أو التاريخ المرضي المقابل حسب الإفادة الموثقة. عدم معرفة المعلومة لا يساوي «لا».','patient-records')
rule('سبب الاستخدام|سبب التوقف','اكتب السبب الذي ورد في التاريخ الدوائي لاستخدام الدواء أو إيقافه مع مصدره وتاريخه إن توفر. لا توقف أو تغير علاجًا من هذا السجل دون قرار مختص.','patient-records')

# Newly introduced specialist forms retain their restricted workflow.
rule('اسم المريض من كلمتين على الأقل|الاسم من كلمتين','اكتب اسم المريض من كلمتين على الأقل. راجع الاسم ورقم الهاتف قبل إنشاء ملف جديد لتجنب تكراره.','patient-records')
rule('رقم التليفون','اكتب رقم الهاتف الذي يمكن التواصل معه وفق الحقل. في ملف المريض راجع مطابقته للملف الحالي ولا تنشئ ملفًا مكررًا.','patient-records')
rule('السن بالسنوات','اكتب سن المريض بالسنوات من0 إلى130 حسب البيانات الموثقة. استكمل الأساسيات قبل حفظ ملف أو جلسة جديدة.','patient-records')
rule('سبب طلب الاستعراض','اشرح سبب حاجتك لاستعراض سجلات التخصصات لهذا المريض. لا يتيح الطلب الاستعراض حتى يوافق المدير أو السوبر أدمن.','patient-records')
rule('رقم التليفون أو الملف','اكتب رقم الهاتف الكامل أو رقم الملف للبحث عن المريض الموجود قبل إنشاء ملف جديد.','patient-records')
rule('مدة الاستعراض بالأيام','حدد مدة السماح باستعراض سجلات التخصصات من1 إلى90 يومًا حسب الحاجة. الافتراضي7 أيام، ويمكن للإدارة إلغاء السماح.','patient-records')

rule('الطبيب وعقد الخدمة المعتمد','اختار الطبيب وعقد الخدمة المعتمد والساري لعرض اسمه وكوده ونسبته ووعاء الاستحقاق وخصم المستلزمات وفترة العقد تلقائيًا. كود الطبيب مستقل عن كود الخدمة. إذا كانت الخدمة موجودة افتح سجلها الأصلي. السعر والقسم والمدة تأتي من تعريف الخدمة؛ النسبة المعتمدة للطبيب لا تساوي هامش ربح المركز.','doctor-missing')

